# Python track bank: the Python level check (module s00) and five exercises per module P1-P6.
# Run `python3 tools/build_bank.py` to validate and write data/bank/py.json.
# Each: m module, t title, lv level, sig starter code, p prompt (markdown), tests [[name, snippet, expected]],
# h hints (no full solution), sol reference solution, why (link to data engineering), optional need/avoid [[regex, message]].
# A test snippet runs against your code; the value of its last line is compared with expected (as JSON).
E, M, H = 'Easy', 'Medium', 'Hard'
Y = []
def q(**k): Y.append(k)

# ---------- Python level check (Setup) : one task per Python module ----------
q(m='s00', t='Count trips per city', lv=E, sig='def count_by_city(trips):\n    pass\n',
  p='`trips` is a list of dicts like `{"id": 1, "city": "Pune"}`. Return a dict mapping each city to its number of trips. (Tests Python 1: dicts.)',
  tests=[['two cities', 'count_by_city([{"id": 1, "city": "Pune"}, {"id": 2, "city": "Goa"}, {"id": 3, "city": "Pune"}])', {'Pune': 2, 'Goa': 1}],
         ['empty list', 'count_by_city([])', {}]],
  h=['One number per city: a dict from city to count.', 'Walk the list once and add 1 to the right key.', 'Empty input gives an empty dict.', 'counts = {}\nfor t in trips:\n    counts[t["city"]] = counts.get(t["city"], 0) + 1'],
  sol='def count_by_city(trips):\n    counts = {}\n    for t in trips:\n        counts[t["city"]] = counts.get(t["city"], 0) + 1\n    return counts',
  why='This is GROUP BY city, COUNT(*) written in Python.')
q(m='s00', t='Sort trips by fare', lv=E, sig='def by_fare(trips):\n    pass\n',
  p='Return the trips sorted by `fare` from highest to lowest; ties keep the lower `id` first. Do not change the input list. (Tests Python 2: sorting with keys.)',
  tests=[['order', '[t["id"] for t in by_fare([{"id": 1, "fare": 50}, {"id": 2, "fare": 90}, {"id": 3, "fare": 50}])]', [2, 1, 3]],
         ['input unchanged', 'x = [{"id": 1, "fare": 1}, {"id": 2, "fare": 9}]\nby_fare(x)\n[t["id"] for t in x]', [1, 2]]],
  h=['Highest fare first; for equal fares, lower id first.', 'sorted() takes a key function and returns a new list.', 'list.sort() changes the input; sorted() does not.', 'return sorted(trips, key=lambda t: (-t["fare"], t["id"]))'],
  sol='def by_fare(trips):\n    return sorted(trips, key=lambda t: (-t["fare"], t["id"]))',
  why='ORDER BY fare DESC, id: the same multi-key sort.')
q(m='s00', t='Even numbers, lazily', lv=E, sig='def evens(nums):\n    pass\n',
  p='Write a **generator** that yields only the even numbers from `nums`, in order. It must work on an endless input. (Tests Python 3: generators.)',
  tests=[['list input', 'list(evens([1, 2, 3, 4, 6]))', [2, 4, 6]],
         ['endless input', 'import itertools\ng = evens(itertools.count(1))\n[next(g), next(g), next(g)]', [2, 4, 6]]],
  need=[['yield', 'Use yield so the function is a generator.']],
  h=['Hand back each even number as you meet it.', 'A function with yield pauses after each value.', 'An endless input means you can never build a full list.', 'for x in nums:\n    if x % 2 == 0:\n        yield x'],
  sol='def evens(nums):\n    for x in nums:\n        if x % 2 == 0:\n            yield x',
  why='Generators let a pipeline read a file bigger than memory one row at a time.')
q(m='s00', t='A trip dataclass', lv=E, sig='from dataclasses import dataclass\n\n\n@dataclass\nclass Trip:\n    pass\n',
  p='Make `Trip` a dataclass with fields `trip_id: int` and `fare: float`, and a method `with_tip(pct)` that returns a **new** Trip whose fare is increased by `pct` percent, rounded to 2 decimals. The original is unchanged. (Tests Python 4: classes.)',
  tests=[['tip', 'Trip(1, 100.0).with_tip(10).fare', 110.0],
         ['original kept', 't = Trip(2, 80.0)\nt.with_tip(25)\nt.fare', 80.0],
         ['equality', 'Trip(1, 5.0) == Trip(1, 5.0)', True]],
  h=['Two fields plus one method that builds a new object.', '@dataclass writes __init__ and __eq__ for you.', 'Return Trip(...), do not set self.fare.', 'def with_tip(self, pct):\n    return Trip(self.trip_id, round(self.fare * (1 + pct / 100), 2))'],
  sol='from dataclasses import dataclass\n\n\n@dataclass\nclass Trip:\n    trip_id: int\n    fare: float\n\n    def with_tip(self, pct):\n        return Trip(self.trip_id, round(self.fare * (1 + pct / 100), 2))',
  why='Small immutable records make transformations easy to test.')
q(m='s00', t='Safe integer parsing', lv=E, sig='def safe_int(value, default=0):\n    pass\n',
  p='Return `int(value)`, or `default` if the value cannot be converted (bad text or `None`). (Tests Python 5: exceptions.)',
  tests=[['number text', 'safe_int("42")', 42], ['bad text', 'safe_int("4x2")', 0], ['None', 'safe_int(None, -1)', -1]],
  avoid=[[r'except\s*:', 'Catch the specific errors (ValueError, TypeError), not everything.']],
  h=['Try the conversion; fall back if it fails.', 'int("x") raises ValueError; int(None) raises TypeError.', 'A bare except also hides typos and Ctrl+C. Name the errors.', 'try:\n    return int(value)\nexcept (ValueError, TypeError):\n    return default'],
  sol='def safe_int(value, default=0):\n    try:\n        return int(value)\n    except (ValueError, TypeError):\n        return default',
  why='Bad rows in a feed should be handled on purpose, not crash the job or vanish silently.')
q(m='s00', t='Split work between workers', lv=E, sig='def split_ranges(total, workers):\n    pass\n',
  p='Split the row numbers `0 .. total-1` into `workers` ranges `[start, end)` as evenly as possible; earlier ranges take the extra rows. Return a list of `[start, end]` lists. (Tests Python 6: dividing work for parallel jobs.)',
  tests=[['even', 'split_ranges(10, 2)', [[0, 5], [5, 10]]], ['uneven', 'split_ranges(10, 3)', [[0, 4], [4, 7], [7, 10]]], ['more workers than rows', 'split_ranges(2, 3)', [[0, 1], [1, 2], [2, 2]]]],
  h=['Every worker gets total // workers rows, and some get one more.', 'The first total % workers ranges get the extra row.', 'A worker can get an empty range.', 'base, extra = divmod(total, workers)\nstart = 0\nfor i in range(workers):\n    size = base + (1 if i < extra else 0)\n    ...'],
  sol='def split_ranges(total, workers):\n    base, extra = divmod(total, workers)\n    out, start = [], 0\n    for i in range(workers):\n        size = base + (1 if i < extra else 0)\n        out.append([start, start + size])\n        start += size\n    return out',
  why='Spark splits files into partitions the same way so tasks finish at about the same time.')

# ---------- P1 core types and cost ----------
q(m='p01', t='Remove duplicates, keep order', lv=E, sig='def dedupe_keep_order(xs):\n    pass\n',
  p='Return a new list with duplicates removed, keeping the first occurrence of each value in its original position. It must handle 12,000 values in well under a second.',
  tests=[['basic', 'dedupe_keep_order([3, 1, 3, 2, 1])', [3, 1, 2]], ['empty', 'dedupe_keep_order([])', []], ['strings', 'dedupe_keep_order(["a", "b", "a"])', ['a', 'b']],
         ['large input: 12,000 values under 0.3 s', 'import time\nt0 = time.perf_counter()\nr = dedupe_keep_order(list(range(6000)) * 2)\nlen(r) == 6000 and time.perf_counter() - t0 < 0.3', True]],
  h=['Keep a value only the first time you see it.', '`x in some_list` scans the whole list: O(n). `x in some_set` is O(1).', 'Order matters, so a set alone is not enough: you need the set and an output list.', 'seen, out = set(), []\nfor x in xs:\n    if x not in seen:\n        seen.add(x)\n        out.append(x)'],
  sol='def dedupe_keep_order(xs):\n    seen, out = set(), []\n    for x in xs:\n        if x not in seen:\n            seen.add(x)\n            out.append(x)\n    return out',
  why='Deduplicating events by id is a daily job; with a list it is O(n²) and a big batch never finishes.')
q(m='p01', t='Top words', lv=M, sig='def top_words(text, k):\n    pass\n',
  p='Split `text` on whitespace, lower-case each word, and return the `k` most common words as `[word, count]` pairs, highest count first; ties sorted alphabetically.',
  tests=[['basic', 'top_words("a b A c b a", 2)', [['a', 3], ['b', 2]]], ['tie broken by word', 'top_words("x y z y x", 2)', [['x', 2], ['y', 2]]], ['k larger than words', 'top_words("one", 3)', [['one', 1]]]],
  h=['Count every word, then pick the top k by a two-part rule.', 'collections.Counter counts in one line.', 'Counter.most_common does not sort ties by word, so sort yourself.', 'c = Counter(text.lower().split())\nreturn [[w, n] for w, n in sorted(c.items(), key=lambda p: (-p[1], p[0]))[:k]]'],
  sol='def top_words(text, k):\n    from collections import Counter\n    c = Counter(text.lower().split())\n    return [[w, n] for w, n in sorted(c.items(), key=lambda p: (-p[1], p[0]))[:k]]',
  why='Top-N by count with a deterministic tie-break is a staple of SQL and Python screens alike.')
q(m='p01', t='Group rows by a field', lv=E, sig='def group_by(rows, key):\n    pass\n',
  p='Return a dict mapping each value of `row[key]` to the list of rows with that value, keeping the original row order inside each group.',
  tests=[['group', 'r = group_by([{"c": "x", "v": 1}, {"c": "y", "v": 2}, {"c": "x", "v": 3}], "c")\n[[k, [x["v"] for x in r[k]]] for k in sorted(r)]', [['x', [1, 3]], ['y', [2]]]], ['empty', 'group_by([], "c")', {}]],
  h=['One list per distinct value.', 'collections.defaultdict(list) creates the list the first time a key appears.', 'Return a plain dict if you like: dict(d).', 'groups = defaultdict(list)\nfor r in rows:\n    groups[r[key]].append(r)'],
  sol='def group_by(rows, key):\n    from collections import defaultdict\n    groups = defaultdict(list)\n    for r in rows:\n        groups[r[key]].append(r)\n    return dict(groups)',
  why='Grouping before writing is how you write one file per partition.')
q(m='p01', t='Tail of a stream', lv=M, sig='def last_n_lines(lines, n):\n    pass\n',
  p='`lines` may be a list **or a generator** too big to hold in memory. Return the last `n` items as a list, like `tail -n`. Keep only `n` items in memory at a time.',
  tests=[['list', 'last_n_lines(["a", "b", "c", "d"], 2)', ['c', 'd']], ['generator', 'last_n_lines((str(i) for i in range(100000)), 3)', ['99997', '99998', '99999']], ['n bigger than input', 'last_n_lines(["a"], 5)', ['a']], ['n is zero', 'last_n_lines(["a", "b"], 0)', []]],
  h=['You only ever need the newest n lines.', 'You cannot slice a generator. Walk it once.', 'collections.deque(maxlen=n) drops the oldest item automatically.', 'from collections import deque\nreturn list(deque(lines, maxlen=n))'],
  sol='def last_n_lines(lines, n):\n    from collections import deque\n    return list(deque(lines, maxlen=n))',
  why='Your on-call agent reads the tail of a huge Airflow log exactly like this.')
q(m='p01', t='Count log levels', lv=M, sig='def level_counts(lines):\n    pass\n',
  p='Each good line looks like `2026-10-01T10:00:00 ERROR trips-ingest failed`: timestamp, level, then a message. Return a dict of level to count. Skip blank lines and lines with fewer than three parts; count those skipped lines under the key `"BAD"` (only if there are any).',
  tests=[['levels', 'level_counts(["t INFO a", "t ERROR b c", "t INFO d"])', {'INFO': 2, 'ERROR': 1}], ['bad lines', 'level_counts(["t INFO a", "", "junk", "t WARN x"])', {'INFO': 1, 'WARN': 1, 'BAD': 2}], ['nothing', 'level_counts([])', {}]],
  h=['Split each line; the level is the second part.', 'line.split(maxsplit=2) gives at most three parts.', 'Blank lines split into []: that is a bad line too.', 'parts = line.split(maxsplit=2)\nif len(parts) < 3:\n    counts["BAD"] = ...'],
  sol='def level_counts(lines):\n    counts = {}\n    for line in lines:\n        parts = line.split(maxsplit=2)\n        key = parts[1] if len(parts) == 3 else "BAD"\n        counts[key] = counts.get(key, 0) + 1\n    return counts',
  why='Counting bad rows instead of crashing or dropping them silently is what makes a pipeline trustworthy.')

# ---------- P2 functions ----------
q(m='p02', t='Sort by three keys', lv=E, sig='def sort_trips(trips):\n    pass\n',
  p='Sort trips by `city` A to Z, then `fare` highest first, then `id` lowest first. Return a new list.',
  tests=[['order', '[t["id"] for t in sort_trips([{"id": 3, "city": "B", "fare": 10}, {"id": 1, "city": "A", "fare": 5}, {"id": 2, "city": "A", "fare": 9}, {"id": 4, "city": "A", "fare": 9}])]', [2, 4, 1, 3]]],
  h=['Three rules, applied in order.', 'A key function can return a tuple; tuples compare item by item.', 'Negate a number to sort it descending inside an ascending sort.', 'key=lambda t: (t["city"], -t["fare"], t["id"])'],
  sol='def sort_trips(trips):\n    return sorted(trips, key=lambda t: (t["city"], -t["fare"], t["id"]))',
  why='Deterministic ordering makes test output and diffs stable.')
q(m='p02', t='A counter made from a closure', lv=E, sig='def make_counter():\n    pass\n',
  p='`make_counter()` returns a function. Each call of that function returns the next number: 1, then 2, then 3. Two counters must not share their count. Do not use a global variable.',
  tests=[['counts up', 'c = make_counter()\n[c(), c(), c()]', [1, 2, 3]], ['independent', 'a = make_counter()\nb = make_counter()\na(); a()\nb()', 1]],
  avoid=[[r'\bglobal\b', 'Keep the count inside the closure, not in a global.']],
  h=['The inner function needs to remember a number between calls.', 'A function defined inside another can see the outer variables.', 'To change an outer variable, declare it nonlocal.', 'def make_counter():\n    n = 0\n    def nxt():\n        nonlocal n\n        ...\n    return nxt'],
  sol='def make_counter():\n    n = 0\n    def nxt():\n        nonlocal n\n        n += 1\n        return n\n    return nxt',
  why='Closures are how decorators and callback-based libraries keep state.')
q(m='p02', t='Compose a pipeline', lv=M, sig='def pipeline(*funcs):\n    pass\n',
  p='`pipeline(f, g, h)` returns a function `p` where `p(x) == h(g(f(x)))`: steps run left to right. With no functions, `p(x)` returns `x` unchanged.',
  tests=[['three steps', 'pipeline(str.strip, str.lower, len)("  AbC ")', 3], ['order matters', 'pipeline(lambda x: x + 1, lambda x: x * 10)(1)', 20], ['no steps', 'pipeline()(5)', 5]],
  h=['Return a new function that feeds each step the previous result.', '*funcs collects the steps into a tuple.', 'An empty tuple means the loop never runs and x comes back as it was.', 'def run(x):\n    for f in funcs:\n        x = f(x)\n    return x\nreturn run'],
  sol='def pipeline(*funcs):\n    def run(x):\n        for f in funcs:\n            x = f(x)\n        return x\n    return run',
  why='Transformation steps composed in order are what every ETL framework does under the hood.')
q(m='p02', t='A retry decorator', lv=M, sig='def retry(times):\n    pass\n',
  p='Write a decorator factory: `@retry(3)` calls the function up to 3 times in total. If a call succeeds, return its result. If all attempts raise, re-raise the last exception. The wrapped function must keep its `__name__` (use `functools.wraps`).',
  tests=[['succeeds on third try', 'calls = []\n@retry(3)\ndef flaky():\n    calls.append(1)\n    if len(calls) < 3:\n        raise ValueError("boom")\n    return "ok"\n[flaky(), len(calls)]', ['ok', 3]],
         ['gives up', 'n = []\n@retry(2)\ndef bad():\n    n.append(1)\n    raise KeyError("x")\ntry:\n    bad()\n    r = "no error"\nexcept KeyError:\n    r = "KeyError"\n[r, len(n)]', ['KeyError', 2]],
         ['keeps the name', '@retry(2)\ndef load_trips():\n    return 1\nload_trips.__name__', 'load_trips'],
         ['passes arguments', '@retry(1)\ndef add(a, b=0):\n    return a + b\nadd(2, b=3)', 5]],
  need=[['wraps', 'Use functools.wraps so the wrapped function keeps its name and docstring.']],
  h=['Three layers: retry(times) returns a decorator; the decorator returns a wrapper.', 'The wrapper loops `times` times and returns on the first success.', 'Remember the last exception and raise it after the loop. Pass *args and **kwargs through.', 'def retry(times):\n    def deco(fn):\n        @functools.wraps(fn)\n        def wrapper(*args, **kwargs):\n            ...\n        return wrapper\n    return deco'],
  sol='import functools\n\n\ndef retry(times):\n    def deco(fn):\n        @functools.wraps(fn)\n        def wrapper(*args, **kwargs):\n            last = None\n            for _ in range(times):\n                try:\n                    return fn(*args, **kwargs)\n                except Exception as e:\n                    last = e\n            raise last\n        return wrapper\n    return deco',
  why='Every API ingestion job needs retries; interviewers ask you to write this decorator live.')
q(m='p02', t='Clean records with rules', lv=M, sig='def clean_records(records, rules):\n    pass\n',
  p='`rules` maps a field name to a function. Return **new** dicts where each field that has a rule is replaced by `rule(value)`; other fields are copied. Fields named in rules but missing from a record are skipped. The input records must not change.',
  tests=[['apply rules', 'clean_records([{"city": " pune ", "fare": "12.5", "id": 1}], {"city": lambda s: s.strip().title(), "fare": float})', [{'city': 'Pune', 'fare': 12.5, 'id': 1}]],
         ['input unchanged', 'src = [{"city": " x "}]\nclean_records(src, {"city": str.strip})\nsrc', [{'city': ' x '}]],
         ['missing field skipped', 'clean_records([{"id": 2}], {"fare": float})', [{'id': 2}]]],
  h=['Build a new dict per record.', 'A dict comprehension can choose rule(value) or value per key.', 'Iterate over the record\'s own keys so missing fields never appear.', 'return [{k: rules[k](v) if k in rules else v for k, v in r.items()} for r in records]'],
  sol='def clean_records(records, rules):\n    return [{k: rules[k](v) if k in rules else v for k, v in r.items()} for r in records]',
  why='Config-driven cleaning (a dict of rules) beats a 300-line if/else and is easy to test.')

# ---------- P3 iterators and generators ----------
q(m='p03', t='Take the first n', lv=E, sig='def take(iterable, n):\n    pass\n',
  p='Return the first `n` items of any iterable as a list. It must work on endless iterables.',
  tests=[['list', 'take([5, 6, 7], 2)', [5, 6]], ['endless', 'import itertools\ntake(itertools.count(10), 3)', [10, 11, 12]], ['short input', 'take("ab", 5)', ['a', 'b']]],
  h=['Stop after n items, even if more exist.', 'itertools.islice is slicing for iterators.', 'Slicing [:n] does not work on generators.', 'from itertools import islice\nreturn list(islice(iterable, n))'],
  sol='def take(iterable, n):\n    from itertools import islice\n    return list(islice(iterable, n))',
  why='Previewing the first rows of a stream without reading it all is what LIMIT does.')
q(m='p03', t='Chunk a stream', lv=M, sig='def chunked(iterable, size):\n    pass\n',
  p='Write a generator that yields lists of `size` items; the last list may be shorter. Raise `ValueError` if `size` is less than 1. It must be lazy: taking the first chunk of an endless input must work.',
  tests=[['chunks', 'list(chunked(range(7), 3))', [[0, 1, 2], [3, 4, 5], [6]]], ['lazy', 'import itertools\nnext(chunked(itertools.count(), 2))', [0, 1]], ['empty', 'list(chunked([], 3))', []],
         ['bad size', 'try:\n    list(chunked([1], 0))\n    r = "no error"\nexcept ValueError:\n    r = "ValueError"\nr', 'ValueError']],
  need=[['yield', 'Make it a generator with yield.']],
  h=['Collect items into a buffer; hand it out when it is full.', 'Yield the buffer, then start a new one. After the loop, yield what is left if anything.', 'Check size before the loop. Note: in a generator the check runs on the first next().', 'buf = []\nfor x in iterable:\n    buf.append(x)\n    if len(buf) == size:\n        yield buf\n        buf = []'],
  sol='def chunked(iterable, size):\n    if size < 1:\n        raise ValueError("size must be at least 1")\n    buf = []\n    for x in iterable:\n        buf.append(x)\n        if len(buf) == size:\n            yield buf\n            buf = []\n    if buf:\n        yield buf',
  why='Inserting into a database or calling an API in batches of 1,000 is this function.')
q(m='p03', t='Read CSV lines lazily', lv=M, sig='def read_rows(lines):\n    pass\n',
  p='`lines` is an iterable of CSV text lines; the first is the header. Yield one dict per data row, skipping blank lines. Values stay strings. Quoted commas must work, so use the `csv` module.',
  tests=[['rows', 'list(read_rows(["id,city", "1,Pune", "", "2,Goa"]))', [{'id': '1', 'city': 'Pune'}, {'id': '2', 'city': 'Goa'}]],
         ['quoted comma', 'list(read_rows(["id,name", \'1,"Rao, Asha"\']))', [{'id': '1', 'name': 'Rao, Asha'}]],
         ['lazy', 'def src():\n    yield "id"\n    yield "1"\n    raise RuntimeError("read too far")\nnext(read_rows(src()))', {'id': '1'}]],
  need=[['csv', 'Use the csv module so quoting is handled correctly.']],
  h=['A header line, then rows that become dicts.', 'csv.DictReader accepts any iterable of lines, including a generator.', 'DictReader yields an empty row for a blank line? Test it; skip rows with no values.', 'import csv\nfor row in csv.DictReader(lines):\n    if any(row.values()):\n        yield row'],
  sol='def read_rows(lines):\n    import csv\n    for row in csv.DictReader(lines):\n        if any(v for v in row.values()):\n            yield dict(row)',
  why='Splitting on commas breaks on real data. Lazy reading keeps memory flat on a 10 GB file.')
q(m='p03', t='Runs of the same value', lv=M, sig='def runs(rows, key):\n    pass\n',
  p='`rows` arrive sorted by time. Return a list of `[value, count]` for each **consecutive** run of the same `row[key]`. A value that appears again later starts a new run.',
  tests=[['runs', 'runs([{"s": "on"}, {"s": "on"}, {"s": "off"}, {"s": "on"}], "s")', [['on', 2], ['off', 1], ['on', 1]]], ['empty', 'runs([], "s")', []]],
  h=['Count how long each value lasts before it changes.', 'itertools.groupby groups consecutive equal keys only. That is exactly what you want here.', 'groupby gives an iterator per group; count it with sum(1 for _ in g).', 'from itertools import groupby\nreturn [[k, sum(1 for _ in g)] for k, g in groupby(rows, key=lambda r: r[key])]'],
  sol='def runs(rows, key):\n    from itertools import groupby\n    return [[k, sum(1 for _ in g)] for k, g in groupby(rows, key=lambda r: r[key])]',
  why='Gaps-and-islands in SQL; groupby in Python. Driver online/offline streaks are a common interview task.')
q(m='p03', t='Deduplicate an endless stream', lv=M, sig='def dedupe_stream(events, key):\n    pass\n',
  p='Write a generator that yields each event the first time its `event[key]` is seen and drops later repeats. The input can be endless, so stay lazy.',
  tests=[['dedupe', 'list(dedupe_stream([{"id": 1}, {"id": 2}, {"id": 1}], "id"))', [{'id': 1}, {'id': 2}]],
         ['endless input', 'import itertools\ng = dedupe_stream(({"id": i // 2} for i in itertools.count()), "id")\n[next(g)["id"] for _ in range(3)]', [0, 1, 2]]],
  need=[['yield', 'Make it a generator with yield.']],
  h=['Remember the keys you have already let through.', 'A set of seen keys, checked before you yield.', 'Never call list() on the input.', 'seen = set()\nfor e in events:\n    k = e[key]\n    if k not in seen:\n        seen.add(k)\n        yield e'],
  sol='def dedupe_stream(events, key):\n    seen = set()\n    for e in events:\n        k = e[key]\n        if k not in seen:\n            seen.add(k)\n            yield e',
  why='Retries make Kafka deliver duplicates. In production the seen-set gets a time limit (a watermark), which you meet in DE 5.')

# Hard, interview length (about 25 minutes each): parse and aggregate a stream
LOGS = "['2026-10-20T08:00:01Z GET /api/trips?id=3 200 120ms', '2026-10-20T08:00:02Z GET /api/trips?id=4 200 80ms', '2026-10-20T08:00:03Z POST /api/trips 201 300ms', '2026-10-20T08:00:04Z GET /api/trips 503 900ms', 'garbage', '2026-10-20T08:00:05Z GET /api/trips 200 fastms', '', '2026-10-20T08:00:06Z GET /api/trips 2000 5ms']"
q(m='p03', t='Latency report from access logs', lv=H, sig='def latency_report(lines):\n    pass\n',
  p='Interview length: about 25 minutes. `lines` is an iterable (maybe a generator over a 20 GB file) of access-log lines such as `2026-10-20T08:00:01Z GET /api/trips?id=3 200 120ms`: time, method, path, status, latency. Return `{"endpoints": {...}, "bad": n}` where each endpoint key is `"METHOD path"` with the query string removed, and its value is `{"n": requests, "p95": latency, "errors": responses with status 500 or more}`. Use the **nearest-rank** p95: sort the latencies and take item `ceil(0.95 * n)` (counting from 1). Skip blank lines. A line is bad (count it, keep going) unless it has exactly five fields, a three-digit status and a whole-number latency ending in `ms`. Read the input once and keep only the latencies, never the lines.',
  tests=[['report', 'latency_report(' + LOGS + ')', {'endpoints': {'GET /api/trips': {'n': 3, 'p95': 900, 'errors': 1}, 'POST /api/trips': {'n': 1, 'p95': 300, 'errors': 0}}, 'bad': 3}],
         ['nearest-rank p95', 'latency_report(["2026-10-20T08:00:00Z GET /x 200 %dms" % v for v in range(20, 0, -1)])["endpoints"]["GET /x"]["p95"]', 19],
         ['one pass over a generator', 'def src():\n    yield "2026-10-20T08:00:00Z GET /a?q=1 200 7ms"\n    yield "2026-10-20T08:00:01Z GET /a 404 9ms"\nlatency_report(src())', {'endpoints': {'GET /a': {'n': 2, 'p95': 9, 'errors': 0}}, 'bad': 0}],
         ['empty', 'latency_report([])', {'endpoints': {}, 'bad': 0}]],
  h=['Split the work: parse one line into (endpoint, status, latency) or "bad", then aggregate.', 'Keep a dict of endpoint to a list of latencies plus an error count; compute p95 only at the end.', 'Traps: `/api/trips?id=3` and `/api/trips` are the same endpoint; a four-digit status or `fastms` is bad; a blank line is neither.', 'parts = line.split()\nif len(parts) != 5: bad += 1; continue\nts, method, path, status, lat = parts\npath = path.split("?", 1)[0]\nnearest rank: xs.sort(); xs[math.ceil(0.95 * len(xs)) - 1]'],
  sol='def latency_report(lines):\n    import math\n    lat, err, bad = {}, {}, 0\n    for line in lines:\n        if not line.strip():\n            continue\n        parts = line.split()\n        if len(parts) != 5:\n            bad += 1\n            continue\n        _, method, path, status, ms = parts\n        if not (len(status) == 3 and status.isdigit() and ms.endswith("ms") and ms[:-2].isdigit()):\n            bad += 1\n            continue\n        ep = method + " " + path.split("?", 1)[0]\n        lat.setdefault(ep, []).append(int(ms[:-2]))\n        err[ep] = err.get(ep, 0) + (int(status) >= 500)\n    out = {}\n    for ep, xs in lat.items():\n        xs.sort()\n        out[ep] = {"n": len(xs), "p95": xs[math.ceil(0.95 * len(xs)) - 1], "errors": err[ep]}\n    return {"endpoints": out, "bad": bad}',
  why='The classic "parse a big log and report per endpoint" round at Meta and Uber. Percentile definitions differ (nearest rank, interpolated, approximate), so say which one you use.')
EV = '[[1, "a"], [3, "b"], [2, "c"], [6, "d"], [4, "e"], [9, "f"], [3, "g"], [10, "h"]]'
q(m='p03', t='Reorder late events with a watermark', lv=H, sig='def reorder(events, lag, late):\n    pass\n',
  p='Interview length: about 25 minutes. `events` is an iterable of `[ts, payload]` that arrive almost in time order: an event can be up to `lag` seconds behind the newest timestamp seen so far. Write a generator that yields the events in timestamp order (equal timestamps keep arrival order) as early as it safely can: after each arrival, yield every buffered event with `ts <= newest - lag` (the watermark). An event older than the last one you yielded is too late: append it to the list `late` and drop it. At the end of the input, yield whatever is left in order. It must work on endless input.',
  tests=[['reorders and drops the late one', 'late = []\nout = list(reorder(' + EV + ', 2, late))\n[out, late]', [[[1, 'a'], [2, 'c'], [3, 'b'], [4, 'e'], [6, 'd'], [9, 'f'], [10, 'h']], [[3, 'g']]]],
         ['equal timestamps keep arrival order', 'list(reorder([[2, "p"], [1, "q"], [2, "r"], [5, "s"]], 1, []))', [[1, 'q'], [2, 'p'], [2, 'r'], [5, 's']]],
         ['lag 0 passes sorted input through', 'list(reorder([[5, "x"], [5, "y"], [7, "z"]], 0, []))', [[5, 'x'], [5, 'y'], [7, 'z']]],
         ['endless input', 'import itertools\ng = reorder(([t, t] for t in itertools.count()), 3, [])\n[next(g), next(g)]', [[0, 0], [1, 1]]],
         ['empty', 'list(reorder([], 5, []))', []]],
  need=[['yield', 'Make it a generator with yield.']],
  h=['Hold events in a buffer until the watermark (newest timestamp minus lag) passes them.', 'A heap of (ts, arrival number, event) gives the smallest timestamp first and keeps ties in arrival order.', 'Traps: an event equal to the last yielded timestamp is not late; the newest timestamp only moves forward; flush the buffer at the end.', 'for seq, ev in enumerate(events):\n    if last is not None and ev[0] < last: late.append(ev); continue\n    newest = ev[0] if newest is None else max(newest, ev[0])\n    heapq.heappush(buf, (ev[0], seq, ev))\n    while buf and buf[0][0] <= newest - lag: ...'],
  sol='def reorder(events, lag, late):\n    import heapq\n    buf, newest, last = [], None, None\n    for seq, ev in enumerate(events):\n        ts = ev[0]\n        if last is not None and ts < last:\n            late.append(ev)\n            continue\n        newest = ts if newest is None else max(newest, ts)\n        heapq.heappush(buf, (ts, seq, ev))\n        while buf and buf[0][0] <= newest - lag:\n            last = buf[0][0]\n            yield heapq.heappop(buf)[2]\n    while buf:\n        yield heapq.heappop(buf)[2]',
  why='This is what Flink and Spark Structured Streaming do with a watermark: wait a bounded time for stragglers, then emit in order and send anything later to a side output.')
CL = '[[0, "a"], [10, "b"], [20, "a"], [100, "a"], [105, "b"], [200, "c"]]'
q(m='p03', t='Sessions from a merged click stream', lv=H, sig='def sessions(clicks, gap):\n    pass\n',
  p='Interview length: about 25 minutes. `clicks` is an iterable of `[ts, user]` for every user, sorted by `ts` (seconds). A user\'s session ends once they are idle for **more than** `gap` seconds. Write a generator that yields `[user, start, end, clicks]` for each session as soon as the stream proves it closed: when a click arrives at time t, first yield every open session whose last click + gap < t, ordered by that close time (last + gap), ties by user. At the end, yield the open sessions in the same order. Memory must grow with the number of open sessions, not with the input, and it must work on endless input.',
  tests=[['closes in order', 'list(sessions(' + CL + ', 30))', [['b', 10, 10, 1], ['a', 0, 20, 2], ['a', 100, 100, 1], ['b', 105, 105, 1], ['c', 200, 200, 1]]],
         ['exactly gap apart stays open', 'list(sessions([[0, "u"], [30, "u"], [61, "u"]], 30))', [['u', 0, 30, 2], ['u', 61, 61, 1]]],
         ['ties by user', 'list(sessions([[0, "b"], [0, "a"], [50, "c"]], 10))', [['a', 0, 0, 1], ['b', 0, 0, 1], ['c', 50, 50, 1]]],
         ['endless input', 'import itertools\ng = sessions(([t * 100, "x"] for t in itertools.count()), 10)\n[next(g), next(g)]', [['x', 0, 0, 1], ['x', 100, 100, 1]]],
         ['empty', 'list(sessions([], 30))', []]],
  need=[['yield', 'Make it a generator with yield.']],
  h=['Keep the open session per user: start, last click, count.', 'A heap of (last + gap, user) tells you which session closes first; entries go stale when the user clicks again, so check them when you pop (lazy deletion).', 'Traps: idle exactly `gap` is still the same session; one click from another user is enough to close a session; flush at the end in close order.', 'open[user] = [start, last, n]\nheap: (last + gap, user, last)\nwhile heap and heap[0][0] < t:\n    close, u, last = heappop(heap)\n    if u in open and open[u][1] == last: yield ...; del open[u]'],
  sol='def sessions(clicks, gap):\n    import heapq\n    open_, heap = {}, []\n    def close_until(t):\n        while heap and (t is None or heap[0][0] < t):\n            _, u, last = heapq.heappop(heap)\n            s = open_.get(u)\n            if s and s[1] == last:\n                del open_[u]\n                yield [u, s[0], s[1], s[2]]\n    for ts, user in clicks:\n        yield from close_until(ts)\n        s = open_.get(user)\n        if s:\n            s[1], s[2] = ts, s[2] + 1\n        else:\n            open_[user] = [ts, ts, 1]\n        heapq.heappush(heap, (ts + gap, user, ts))\n    yield from close_until(None)',
  why='Sessionisation in a stream job: the window closes on event time, not when the user leaves, which is why sessions come out in close order.')

# ---------- P4 classes and types ----------
q(m='p04', t='A validated Trip class', lv=E, sig='class Trip:\n    def __init__(self, trip_id, fare, km):\n        pass\n',
  p='`Trip(trip_id, fare, km)` raises `ValueError` if `fare` or `km` is negative. Add a read-only property `fare_per_km` (fare divided by km, rounded to 2; `0.0` when km is 0) and a `__repr__` that returns `Trip(7, fare=120.0, km=8.0)` for those values.',
  tests=[['per km', 'Trip(1, 100.0, 8.0).fare_per_km', 12.5], ['zero km', 'Trip(2, 50.0, 0).fare_per_km', 0.0],
         ['negative fare', 'try:\n    Trip(3, -1.0, 2.0)\n    r = "no error"\nexcept ValueError:\n    r = "ValueError"\nr', 'ValueError'],
         ['repr', 'repr(Trip(7, 120.0, 8.0))', 'Trip(7, fare=120.0, km=8.0)'],
         ['read-only', 't = Trip(1, 10.0, 1.0)\ntry:\n    t.fare_per_km = 5\n    r = "changed"\nexcept AttributeError:\n    r = "read-only"\nr', 'read-only']],
  need=[['@property', 'Use @property for fare_per_km.']],
  h=['Check inputs in __init__, compute fare_per_km on demand.', 'A @property looks like an attribute but runs a method; without a setter it cannot be assigned.', 'Guard the divide by zero.', 'def __repr__(self):\n    return f"Trip({self.trip_id}, fare={self.fare}, km={self.km})"'],
  sol='class Trip:\n    def __init__(self, trip_id, fare, km):\n        if fare < 0 or km < 0:\n            raise ValueError("fare and km must not be negative")\n        self.trip_id, self.fare, self.km = trip_id, fare, km\n\n    @property\n    def fare_per_km(self):\n        return round(self.fare / self.km, 2) if self.km else 0.0\n\n    def __repr__(self):\n        return f"Trip({self.trip_id}, fare={self.fare}, km={self.km})"',
  why='Rejecting bad values at the edge (in the constructor) keeps them out of every table downstream.')
q(m='p04', t='Money that refuses to mix currencies', lv=M, sig='from dataclasses import dataclass\n\n\nclass Money:\n    pass\n',
  p='Make `Money` a **frozen** dataclass with `amount: int` (in paise) and `currency: str`. `Money(100, "INR") + Money(50, "INR")` gives `Money(150, "INR")`. Adding different currencies raises `ValueError`. Changing a field after creation must fail.',
  tests=[['add', 'Money(100, "INR") + Money(50, "INR") == Money(150, "INR")', True],
         ['mixed currency', 'try:\n    Money(1, "INR") + Money(1, "USD")\n    r = "no error"\nexcept ValueError:\n    r = "ValueError"\nr', 'ValueError'],
         ['frozen', 'm = Money(5, "INR")\ntry:\n    m.amount = 6\n    r = "changed"\nexcept Exception as e:\n    r = type(e).__name__\nr', 'FrozenInstanceError'],
         ['hashable', 'len({Money(1, "INR"), Money(1, "INR")})', 1]],
  need=[['frozen\\s*=\\s*True', 'Use @dataclass(frozen=True).'], ['__add__', 'Define __add__ so + works.']],
  h=['A value object: two fields, immutable, with + defined.', '@dataclass(frozen=True) blocks assignment and makes it hashable.', 'Check currencies match before adding.', 'def __add__(self, other):\n    if self.currency != other.currency:\n        raise ValueError(...)\n    return Money(self.amount + other.amount, self.currency)'],
  sol='from dataclasses import dataclass\n\n\n@dataclass(frozen=True)\nclass Money:\n    amount: int\n    currency: str\n\n    def __add__(self, other):\n        if self.currency != other.currency:\n            raise ValueError("cannot add " + self.currency + " and " + other.currency)\n        return Money(self.amount + other.amount, self.currency)',
  why='Store money as integer paise, never floats; mixing currencies silently is a classic finance-data bug.')
q(m='p04', t='A buffer that flushes itself', lv=M, sig='class RowBuffer:\n    def __init__(self, max_rows, on_flush):\n        pass\n',
  p='`RowBuffer(max_rows, on_flush)` collects rows with `add(row)`. When it holds `max_rows` rows it calls `on_flush(rows)` with them and empties itself. `flush()` sends whatever is left (and does nothing when empty). `len(buf)` gives the rows waiting.',
  tests=[['auto flush', 'out = []\nb = RowBuffer(2, out.append)\nfor i in range(5):\n    b.add(i)\n[out, len(b)]', [[[0, 1], [2, 3]], 1]],
         ['final flush', 'out = []\nb = RowBuffer(3, out.append)\nb.add("a")\nb.flush()\nb.flush()\nout', [['a']]],
         ['flushed list is a copy', 'out = []\nb = RowBuffer(1, out.append)\nb.add(1)\nb.add(2)\nout', [[1], [2]]]],
  need=[['__len__', 'Define __len__ so len(buffer) works.']],
  h=['State: a list of rows and a callback.', 'add() appends, then flushes if the list is full.', 'Hand the callback the list and then start a new list; do not clear the list you handed over.', 'def flush(self):\n    if self.rows:\n        rows, self.rows = self.rows, []\n        self.on_flush(rows)'],
  sol='class RowBuffer:\n    def __init__(self, max_rows, on_flush):\n        self.max_rows, self.on_flush, self.rows = max_rows, on_flush, []\n\n    def add(self, row):\n        self.rows.append(row)\n        if len(self.rows) >= self.max_rows:\n            self.flush()\n\n    def flush(self):\n        if self.rows:\n            rows, self.rows = self.rows, []\n            self.on_flush(rows)\n\n    def __len__(self):\n        return len(self.rows)',
  why='Kafka producers and database writers batch exactly like this; the copy bug is a real production incident.')
q(m='p04', t='Validation rules as classes', lv=M, sig='class NotNull:\n    pass\n\n\nclass InRange:\n    pass\n\n\ndef validate(rows, rules):\n    pass\n',
  p='Each rule has a `check(row)` method returning `None` when the row is fine or a message string. `NotNull(field)` fails with `"<field> is null"` when the field is missing or None. `InRange(field, lo, hi)` fails with `"<field> out of range"` when the value is outside `lo..hi` (skip None; NotNull handles it). `validate(rows, rules)` returns `[row_index, message]` for every failure, in row order then rule order.',
  tests=[['failures', 'validate([{"fare": 10}, {"fare": None}, {"fare": 999}], [NotNull("fare"), InRange("fare", 0, 500)])', [[1, 'fare is null'], [2, 'fare out of range']]],
         ['all good', 'validate([{"fare": 1}], [InRange("fare", 0, 5)])', []],
         ['missing field', 'NotNull("km").check({})', 'km is null']],
  h=['Two small classes with the same method name, and one loop over rows and rules.', 'The validator does not care which class a rule is, only that it has check(): duck typing.', 'Use row.get(field) so a missing field reads as None.', 'out = []\nfor i, row in enumerate(rows):\n    for rule in rules:\n        msg = rule.check(row)\n        if msg:\n            out.append([i, msg])'],
  sol='class NotNull:\n    def __init__(self, field):\n        self.field = field\n\n    def check(self, row):\n        return self.field + " is null" if row.get(self.field) is None else None\n\n\nclass InRange:\n    def __init__(self, field, lo, hi):\n        self.field, self.lo, self.hi = field, lo, hi\n\n    def check(self, row):\n        v = row.get(self.field)\n        if v is not None and not (self.lo <= v <= self.hi):\n            return self.field + " out of range"\n        return None\n\n\ndef validate(rows, rules):\n    out = []\n    for i, row in enumerate(rows):\n        for rule in rules:\n            msg = rule.check(row)\n            if msg:\n                out.append([i, msg])\n    return out',
  why='This is how Great Expectations and dbt tests are built, and a common low-level design question.')
q(m='p04', t='An event log you can loop over', lv=E, sig='class EventLog:\n    def __init__(self):\n        pass\n',
  p='`EventLog` stores events (dicts with an `"id"`) via `append(event)`. Make it work with Python\'s built-ins: `len(log)`, `for e in log` (oldest first) and `"e7" in log` (true if an event with that id was appended). Membership must not scan the list.',
  tests=[['len and iter', 'log = EventLog()\nlog.append({"id": "a"})\nlog.append({"id": "b"})\n[len(log), [e["id"] for e in log]]', [2, ['a', 'b']]],
         ['contains', 'log = EventLog()\nlog.append({"id": "e7"})\n["e7" in log, "e8" in log]', [True, False]]],
  need=[['__contains__', 'Define __contains__.'], ['__iter__', 'Define __iter__.']],
  h=['Python calls special methods for built-ins: len() calls __len__, for calls __iter__, in calls __contains__.', 'Keep a list for order and a set of ids for fast membership.', '__iter__ can return iter(self.events).', 'def __contains__(self, event_id):\n    return event_id in self.ids'],
  sol='class EventLog:\n    def __init__(self):\n        self.events, self.ids = [], set()\n\n    def append(self, event):\n        self.events.append(event)\n        self.ids.add(event["id"])\n\n    def __len__(self):\n        return len(self.events)\n\n    def __iter__(self):\n        return iter(self.events)\n\n    def __contains__(self, event_id):\n        return event_id in self.ids',
  why='Objects that behave like built-ins are easier to use and test, and LLD interviewers notice.')

# ---------- P5 code that survives production ----------
q(m='p05', t='A custom exception with context', lv=E, sig='class BadAmount(ValueError):\n    pass\n\n\ndef parse_amount(text):\n    pass\n',
  p='`parse_amount(text)` returns `float(text)` after stripping spaces and a leading `"₹"`. If it cannot convert, raise `BadAmount` with the message `bad amount: <original text>` and chain the original error (`raise ... from e`).',
  tests=[['parses', 'parse_amount(" ₹12.50 ")', 12.5],
         ['raises BadAmount', 'try:\n    parse_amount("12,5x")\n    r = "no error"\nexcept BadAmount as e:\n    r = str(e)\nr', 'bad amount: 12,5x'],
         ['still a ValueError', 'issubclass(BadAmount, ValueError)', True],
         ['chained', 'try:\n    parse_amount("x")\nexcept BadAmount as e:\n    r = type(e.__cause__).__name__\nr', 'ValueError']],
  need=[[r'raise\s+BadAmount\(.*\)\s+from', 'Chain the original error with raise ... from e.']],
  h=['Clean the text, try float, and translate the error.', 'A custom exception that subclasses ValueError can still be caught as ValueError.', '`raise New(...) from e` keeps the original error in the traceback.', 'try:\n    return float(text.strip().lstrip("₹").strip())\nexcept ValueError as e:\n    raise BadAmount("bad amount: " + text) from e'],
  sol='class BadAmount(ValueError):\n    pass\n\n\ndef parse_amount(text):\n    try:\n        return float(text.strip().lstrip("₹").strip())\n    except ValueError as e:\n        raise BadAmount("bad amount: " + text) from e',
  why='An error that names the bad value saves an hour of digging at 3 a.m.')
q(m='p05', t='A timing context manager', lv=M, sig='from contextlib import contextmanager\n\n\ndef timer(stats, name):\n    pass\n',
  p='`with timer(stats, "load"): ...` stores the elapsed seconds in `stats["load"]`. The time must be recorded even if the block raises, and the error must still reach the caller. Use `contextlib.contextmanager` and `time.perf_counter()`.',
  tests=[['records', 'stats = {}\nwith timer(stats, "load"):\n    sum(range(1000))\n["load" in stats, stats["load"] >= 0]', [True, True]],
         ['records on error', 'stats = {}\ntry:\n    with timer(stats, "bad"):\n        raise KeyError("x")\nexcept KeyError:\n    r = "raised"\n[r, "bad" in stats]', ['raised', True]]],
  need=[['finally', 'Record the time in a finally block so it runs on errors too.'], ['yield', 'A @contextmanager function yields once.']],
  h=['Start a clock, run the block, store the time no matter what.', 'In a @contextmanager function the block runs where you yield.', 'try: yield / finally: record. Do not catch the error.', '@contextmanager\ndef timer(stats, name):\n    t0 = time.perf_counter()\n    try:\n        yield\n    finally:\n        stats[name] = time.perf_counter() - t0'],
  sol='import time\nfrom contextlib import contextmanager\n\n\n@contextmanager\ndef timer(stats, name):\n    t0 = time.perf_counter()\n    try:\n        yield\n    finally:\n        stats[name] = time.perf_counter() - t0',
  why='Timing each pipeline step, even the failed ones, is the first observability you add.')
q(m='p05', t='Commit or roll back', lv=M, sig='class Transaction:\n    def __init__(self, log):\n        pass\n',
  p='Write a class-based context manager. `with Transaction(log):` appends `"begin"` on entry; on a clean exit it appends `"commit"`; if the block raises it appends `"rollback"` and lets the exception continue.',
  tests=[['commit', 'log = []\nwith Transaction(log):\n    log.append("work")\nlog', ['begin', 'work', 'commit']],
         ['rollback', 'log = []\ntry:\n    with Transaction(log):\n        raise ValueError("bad row")\nexcept ValueError:\n    log.append("caught")\nlog', ['begin', 'rollback', 'caught']]],
  need=[['__exit__', 'Define __enter__ and __exit__.']],
  h=['__enter__ runs at the start of the with block, __exit__ at the end.', '__exit__ gets (exc_type, exc, tb); exc_type is None on a clean exit.', 'Returning True from __exit__ swallows the error. Return False (or nothing).', 'def __exit__(self, exc_type, exc, tb):\n    self.log.append("commit" if exc_type is None else "rollback")\n    return False'],
  sol='class Transaction:\n    def __init__(self, log):\n        self.log = log\n\n    def __enter__(self):\n        self.log.append("begin")\n        return self\n\n    def __exit__(self, exc_type, exc, tb):\n        self.log.append("commit" if exc_type is None else "rollback")\n        return False',
  why='Database connections, file writers and locks all use this pattern so cleanup cannot be forgotten.')
q(m='p05', t='Load a batch with a dead-letter list', lv=E, sig='def load_batch(rows):\n    pass\n',
  p='Each row is a dict with `id` and `amount` (text). Convert `amount` with `int()`. Return `{"loaded": [ids that converted], "failed": [[id, error message], ...]}`. One bad row must not stop the others.',
  tests=[['mixed', 'load_batch([{"id": 1, "amount": "10"}, {"id": 2, "amount": "x"}, {"id": 3, "amount": "7"}])', {'loaded': [1, 3], 'failed': [[2, "invalid literal for int() with base 10: 'x'"]]}],
         ['missing field', 'load_batch([{"id": 9}])["failed"][0][0]', 9]],
  avoid=[[r'except\s*:', 'Catch named exceptions, not everything.']],
  h=['Process each row separately and record what happened.', 'Put the try/except inside the loop, not around it.', 'A missing key raises KeyError; bad text raises ValueError.', 'for r in rows:\n    try:\n        int(r["amount"])\n        loaded.append(r["id"])\n    except (KeyError, ValueError) as e:\n        failed.append([r["id"], str(e)])'],
  sol='def load_batch(rows):\n    loaded, failed = [], []\n    for r in rows:\n        try:\n            int(r["amount"])\n            loaded.append(r["id"])\n        except (KeyError, ValueError) as e:\n            failed.append([r["id"], str(e)])\n    return {"loaded": loaded, "failed": failed}',
  why='A dead-letter queue keeps one poison row from blocking a million good ones; you build it for Kafka in DE 5.')
q(m='p05', t='Retry with backoff you can test', lv=M, sig='def retry_call(fn, attempts, base_delay, sleep, retry_on=(ConnectionError,)):\n    pass\n',
  p='Call `fn()` up to `attempts` times. Retry only on exceptions in `retry_on`; anything else is raised at once. Before retry number k (k = 1, 2, …) call `sleep(base_delay * 2 ** (k - 1))`. Do not sleep after the last attempt. Re-raise the last error if every attempt fails. `sleep` is passed in so tests do not wait.',
  tests=[['backoff then success', 'slept, n = [], []\ndef f():\n    n.append(1)\n    if len(n) < 3:\n        raise ConnectionError()\n    return "ok"\n[retry_call(f, 5, 0.5, slept.append), slept]', ['ok', [0.5, 1.0]]],
         ['gives up without a final sleep', 'slept = []\ndef f():\n    raise ConnectionError("down")\ntry:\n    retry_call(f, 3, 1, slept.append)\nexcept ConnectionError:\n    pass\nslept', [1, 2]],
         ['other errors are not retried', 'slept, n = [], []\ndef f():\n    n.append(1)\n    raise ValueError("bad")\ntry:\n    retry_call(f, 3, 1, slept.append)\nexcept ValueError:\n    pass\n[len(n), slept]', [1, []]]],
  h=['A loop over attempts with a try/except.', 'Catch only retry_on. Other exceptions are bugs, not outages: let them out.', 'Sleep only if another attempt follows.', 'for k in range(attempts):\n    try:\n        return fn()\n    except retry_on as e:\n        last = e\n        if k < attempts - 1:\n            sleep(base_delay * 2 ** k)\nraise last'],
  sol='def retry_call(fn, attempts, base_delay, sleep, retry_on=(ConnectionError,)):\n    last = None\n    for k in range(attempts):\n        try:\n            return fn()\n        except retry_on as e:\n            last = e\n            if k < attempts - 1:\n                sleep(base_delay * 2 ** k)\n    raise last',
  why='Passing sleep (and clocks, and clients) in as arguments is what makes production code testable.')

# ---------- P6 concurrency and performance ----------
q(m='p06', t='Merge worker results', lv=E, sig='def merge_counts(parts):\n    pass\n',
  p='Each worker returns a dict of key to count. Combine a list of them into one dict with summed counts.',
  tests=[['merge', 'merge_counts([{"a": 1, "b": 2}, {"b": 3}, {}])', {'a': 1, 'b': 5}], ['none', 'merge_counts([])', {}]],
  h=['Add every worker\'s counts into one total.', 'A Counter supports update() and +.', 'Empty dicts and an empty list both work naturally.', 'total = {}\nfor p in parts:\n    for k, v in p.items():\n        total[k] = total.get(k, 0) + v'],
  sol='def merge_counts(parts):\n    total = {}\n    for p in parts:\n        for k, v in p.items():\n            total[k] = total.get(k, 0) + v\n    return total',
  why='Map then reduce: count in parallel, merge at the end. A Spark aggregation does the same with partial aggregates.')
q(m='p06', t='A token bucket rate limiter', lv=M, sig='class TokenBucket:\n    def __init__(self, rate, capacity):\n        pass\n\n    def allow(self, now):\n        pass\n',
  p='`TokenBucket(rate, capacity)` starts full. Tokens refill at `rate` per second, never above `capacity`. `allow(now)` (now in seconds) refills based on the time since the last call, then spends one token and returns True, or returns False if less than one token is available. The first call sets the clock.',
  tests=[['burst then block', 'b = TokenBucket(1, 2)\n[b.allow(0), b.allow(0), b.allow(0)]', [True, True, False]],
         ['refills', 'b = TokenBucket(2, 2)\nb.allow(0); b.allow(0)\n[b.allow(0.25), b.allow(0.5), b.allow(0.5)]', [False, True, False]],
         ['capped', 'b = TokenBucket(1, 3)\nb.allow(0)\nr = [b.allow(100) for _ in range(4)]\nr', [True, True, True, False]]],
  h=['Keep a token count and the time of the last call.', 'tokens = min(capacity, tokens + (now - last) * rate).', 'Spend a token only when you have a whole one.', 'def allow(self, now):\n    if self.last is not None:\n        self.tokens = min(self.capacity, self.tokens + (now - self.last) * self.rate)\n    self.last = now\n    ...'],
  sol='class TokenBucket:\n    def __init__(self, rate, capacity):\n        self.rate, self.capacity = rate, capacity\n        self.tokens, self.last = capacity, None\n\n    def allow(self, now):\n        if self.last is not None:\n            self.tokens = min(self.capacity, self.tokens + (now - self.last) * self.rate)\n        self.last = now\n        if self.tokens >= 1:\n            self.tokens -= 1\n            return True\n        return False',
  why='API ingestion must respect rate limits; "design a rate limiter" is also a classic system design question.')
q(m='p06', t='Limit concurrent API calls', lv=M, sig='import asyncio\n\n\nasync def fetch_all(ids, fetch, limit):\n    pass\n',
  p='`fetch(id)` is an async function. Call it for every id with **at most `limit` calls running at once** (use `asyncio.Semaphore`), and return the results in the same order as `ids`.',
  tests=[['order and limit', 'import asyncio\nstate = {"now": 0, "peak": 0}\nasync def fetch(i):\n    state["now"] += 1\n    state["peak"] = max(state["peak"], state["now"])\n    await asyncio.sleep(0.001 * (5 - i % 5))\n    state["now"] -= 1\n    return i * 10\nres = asyncio.run(fetch_all(list(range(8)), fetch, 3))\n[res, state["peak"]]', [[0, 10, 20, 30, 40, 50, 60, 70], 3]],
         ['empty', 'import asyncio\nasync def f(i):\n    return i\nasyncio.run(fetch_all([], f, 2))', []]],
  need=[['Semaphore', 'Use asyncio.Semaphore to cap concurrency.'], ['gather', 'Use asyncio.gather to run the calls together and keep their order.']],
  h=['Start all calls, but let only `limit` of them be inside fetch at once.', 'A semaphore is a counter: `async with sem:` waits when it is at zero.', 'asyncio.gather returns results in the order you passed the tasks, not the order they finished.', 'sem = asyncio.Semaphore(limit)\nasync def one(i):\n    async with sem:\n        return await fetch(i)\nreturn await asyncio.gather(*(one(i) for i in ids))'],
  sol='import asyncio\n\n\nasync def fetch_all(ids, fetch, limit):\n    sem = asyncio.Semaphore(limit)\n\n    async def one(i):\n        async with sem:\n            return await fetch(i)\n    return list(await asyncio.gather(*(one(i) for i in ids)))',
  why='Pulling 10,000 pages from an API: sequential takes hours, unlimited gets you banned. A semaphore is the middle.')
q(m='p06', t='Plan file compaction', lv=M, sig='def plan_batches(files, max_bytes):\n    pass\n',
  p='`files` is a list of `[name, size]`. Group them into batches whose total size is at most `max_bytes`, using **first-fit decreasing**: take files largest first (ties by name), put each into the first existing batch it fits in, otherwise start a new batch. A file bigger than `max_bytes` gets its own batch. Return the batches as lists of names, in the order the batches were created.',
  tests=[['packs', 'plan_batches([["a", 40], ["b", 70], ["c", 30], ["d", 60]], 100)', [['b', 'c'], ['d', 'a']]],
         ['oversized alone', 'plan_batches([["big", 500], ["s", 10]], 100)', [['big'], ['s']]],
         ['ties by name', 'plan_batches([["y", 50], ["x", 50], ["z", 50]], 100)', [['x', 'y'], ['z']]]],
  h=['Sort, then place each file into the first batch with room.', 'Track each batch\'s remaining space next to its names.', 'An oversized file never fits anywhere, so it starts its own batch and nothing else joins it.', 'for name, size in sorted(files, key=lambda f: (-f[1], f[0])):\n    for b in batches:\n        if b["free"] >= size: ...'],
  sol='def plan_batches(files, max_bytes):\n    batches = []\n    for name, size in sorted(files, key=lambda f: (-f[1], f[0])):\n        for b in batches:\n            if b["free"] >= size:\n                b["names"].append(name)\n                b["free"] -= size\n                break\n        else:\n            batches.append({"names": [name], "free": max_bytes - size})\n    return [b["names"] for b in batches]',
  why='This is how a compaction job turns 10,000 small files into a few 128 MB ones; you run Iceberg compaction in DE 2.')
q(m='p06', t='Find the slow part', lv=M, sig='def slow_join(trips, drivers):\n    """Return [trip_id, driver_name] for every trip whose driver exists."""\n    out = []\n    for t in trips:\n        for d in drivers:\n            if d["id"] == t["driver_id"]:\n                out.append([t["id"], d["name"]])\n    return out\n',
  p='The starter code is correct but O(trips × drivers). Rewrite `slow_join` so it returns the same result (in trip order) and handles 4,000 trips and 2,000 drivers in under 0.2 seconds.',
  tests=[['same result', 'slow_join([{"id": 1, "driver_id": 7}, {"id": 2, "driver_id": 9}], [{"id": 7, "name": "Asha"}])', [[1, 'Asha']]],
         ['large input under 0.2 s', 'import time\nT = [{"id": i, "driver_id": i % 2500} for i in range(4000)]\nD = [{"id": i, "name": "d" + str(i)} for i in range(2000)]\nt0 = time.perf_counter()\nr = slow_join(T, D)\n[len(r), time.perf_counter() - t0 < 0.2]', [3500, True]]],
  h=['The inner loop searches all drivers for every trip.', 'Build a dict from driver id to name once: O(drivers).', 'Then each trip is one dict lookup: O(1).', 'names = {d["id"]: d["name"] for d in drivers}\nreturn [[t["id"], names[t["driver_id"]]] for t in trips if t["driver_id"] in names]'],
  sol='def slow_join(trips, drivers):\n    names = {d["id"]: d["name"] for d in drivers}\n    return [[t["id"], names[t["driver_id"]]] for t in trips if t["driver_id"] in names]',
  why='This is a nested-loop join versus a hash join: the same choice Spark makes between a sort-merge and a broadcast join.')

# Hard, interview length (about 25 minutes each): data bigger than memory
DISK = 'runs = {}\ndef spill(run):\n    runs[len(runs)] = list(run)\n    return len(runs) - 1\nloads = []\ndef load(i):\n    loads.append(i)\n    return iter(runs[i])\n'
q(m='p06', t='External sort with spill files', lv=H, sig='def external_sort(items, chunk, spill, load):\n    pass\n',
  p='Interview length: about 25 minutes. Sort a stream that does not fit in memory. Read at most `chunk` items, sort them, and pass the sorted run to `spill(run)`, which stores it (on disk, in real life) and returns an id. When the input ends, merge the runs: `load(id)` returns an iterator over one stored run. Write a generator that yields every item in ascending order. Never read more than `chunk` input items before spilling them, and load each run exactly once.',
  tests=[['sorted, in runs of at most chunk', DISK + 'out = list(external_sort(iter([5, 3, 9, 1, 7, 2, 8]), 3, spill, load))\n[out, sorted(len(r) for r in runs.values()), all(r == sorted(r) for r in runs.values()), sorted(loads)]', [[1, 2, 3, 5, 7, 8, 9], [1, 3, 3], True, [0, 1, 2]]],
         ['spills before reading on', DISK + 'def src():\n    for i, x in enumerate([4, 1, 3, 2, 6, 5]):\n        if i >= 2 * (len(runs) + 1):\n            raise RuntimeError("read too far before spilling")\n        yield x\nlist(external_sort(src(), 2, spill, load))', [1, 2, 3, 4, 5, 6]],
         ['merges lazily', DISK + 'pulled = []\ndef load(i):\n    loads.append(i)\n    for x in runs[i]:\n        pulled.append(x)\n        yield x\ng = external_sort(iter(range(9, 0, -1)), 3, spill, load)\nfirst = next(g)\n[first, len(pulled) <= len(runs) + 1]', [1, True]],
         ['duplicates, chunk 1', DISK + 'list(external_sort(iter([2, 2, 1]), 1, spill, load))', [1, 2, 2]],
         ['empty', DISK + '[list(external_sort(iter([]), 4, spill, load)), len(runs)]', [[], 0]]],
  need=[['yield', 'Make it a generator with yield.']],
  h=['Two phases: cut the input into sorted runs, then a k-way merge of the runs.', 'itertools.islice(it, chunk) reads one chunk; heapq.merge(*iterators) merges sorted iterators lazily, holding one item per run.', 'Traps: an empty input makes no runs; a final short chunk is still a run; sorted(items) on the whole input is exactly what you cannot do.', 'it = iter(items)\nids = []\nwhile True:\n    run = sorted(itertools.islice(it, chunk))\n    if not run: break\n    ids.append(spill(run))\nyield from heapq.merge(*(load(i) for i in ids))'],
  sol='def external_sort(items, chunk, spill, load):\n    import heapq, itertools\n    it, ids = iter(items), []\n    while True:\n        run = sorted(itertools.islice(it, chunk))\n        if not run:\n            break\n        ids.append(spill(run))\n    yield from heapq.merge(*[load(i) for i in ids])',
  why='How databases sort when ORDER BY does not fit in memory, and how Spark spills during a sort-based shuffle: sorted runs on disk, then a merge.')
L = '[{"k": 1, "a": "x"}, {"k": 2, "a": "y"}, {"k": 2, "a": "z"}, {"k": 4, "a": "w"}]'
R = '[{"k": 2, "b": 1}, {"k": 2, "b": 2}, {"k": 3, "b": 3}, {"k": 4, "b": 4}]'
q(m='p06', t='Sort-merge join of two streams', lv=H, sig='def merge_join(left, right, key):\n    pass\n',
  p='Interview length: about 25 minutes. `left` and `right` are iterables of dicts, each sorted by `row[key]` ascending; keys can repeat on both sides and either stream can be endless. Write a generator for the inner join: for every pair with equal keys yield `{**l, **r}`, in key order; within one key, left rows in order, and for each left row the right rows in order. A key of `None` never matches (as in SQL) and may appear anywhere. Hold at most one key\'s group of right rows in memory.',
  tests=[['many to many', 'list(merge_join(' + L + ', ' + R + ', "k"))', [{'k': 2, 'a': 'y', 'b': 1}, {'k': 2, 'a': 'y', 'b': 2}, {'k': 2, 'a': 'z', 'b': 1}, {'k': 2, 'a': 'z', 'b': 2}, {'k': 4, 'a': 'w', 'b': 4}]],
         ['None never joins', 'list(merge_join([{"k": None, "a": 1}, {"k": 1, "a": 2}], [{"k": None, "b": 1}, {"k": 1, "b": 2}], "k"))', [{'k': 1, 'a': 2, 'b': 2}]],
         ['one side empty', '[list(merge_join([], ' + R + ', "k")), list(merge_join(' + L + ', [], "k"))]', [[], []]],
         ['endless streams', 'import itertools\ng = merge_join(({"k": i // 2, "a": i} for i in itertools.count()), ({"k": i, "b": i} for i in itertools.count(0, 3)), "k")\n[[r["a"], r["b"]] for r in itertools.islice(g, 3)]', [[0, 0], [1, 0], [6, 3]]],
         ['no matches', 'list(merge_join([{"k": 1}], [{"k": 2}], "k"))', []]],
  need=[['yield', 'Make it a generator with yield.']],
  h=['Walk both streams with one "current row" each; advance whichever side has the smaller key.', 'When keys match, read the whole right group for that key into a list, then pair every left row with that key against it.', 'Traps: moving both pointers on a match loses the many-to-many pairs; skip None keys on both sides; stop when either side runs out.', 'l, r = nxt(L), nxt(R)\nwhile l is not None and r is not None:\n    if l[key] < r[key]: l = nxt(L)\n    elif l[key] > r[key]: r = nxt(R)\n    else: read the right group, then loop over left rows with that key'],
  sol='def merge_join(left, right, key):\n    L, R = iter(left), iter(right)\n    def nxt(it):\n        for row in it:\n            if row[key] is not None:\n                return row\n        return None\n    l, r = nxt(L), nxt(R)\n    while l is not None and r is not None:\n        if l[key] < r[key]:\n            l = nxt(L)\n        elif l[key] > r[key]:\n            r = nxt(R)\n        else:\n            k, group = l[key], []\n            while r is not None and r[key] == k:\n                group.append(r)\n                r = nxt(R)\n            while l is not None and l[key] == k:\n                for g in group:\n                    yield {**l, **g}\n                l = nxt(L)',
  why='Spark\'s default join for two large tables is a sort-merge join; a hot key makes one group huge, which is exactly the skew problem.')
JL = repr(['{"id": "e1", "ts": "2026-10-20T08:15:00Z", "user": "u1", "order": {"total": 10.5}}', '{"id": "e2", "ts": "2026-10-20T14:05:00+05:30", "user": "u2"}', '{"id": "e1", "ts": "2026-10-20T08:15:00Z", "user": "u1", "order": {"total": 99}}',
           '{"id": "e3", "ts": "2026-10-20T09:00:00+00:00", "user": "u1", "order": {"total": "n/a"}}', 'not json', '{"id": "e4", "ts": "2026-10-20T09:59:59Z"}', '{"id": "e5", "ts": "yesterday", "user": "u3"}',
           '{"ts": "2026-10-20T09:10:00Z", "user": "u9"}', '{"id": "e6", "ts": "2026-10-20T10:00:00", "user": "u4"}', '{"id": "e7", "ts": "2026-10-21T00:30:00+01:00", "user": "u1", "order": {"total": 4.25}}', '{"id": "e8", "ts": "2026-10-20T08:59:00Z", "user": "u1", "order": {"total": 0.1}}'])
q(m='p06', t='Hourly rollup from JSON lines, in UTC', lv=H, sig='def hourly_rollup(lines):\n    pass\n',
  p='Interview length: about 25 minutes. Each line is one JSON event: `{"id": ..., "ts": "2026-10-20T14:05:00+05:30", "user": ..., "order": {"total": 12.5}}`. In one pass, return `{"rows": [[hour, events, users, revenue], ...], "bad": n}` with one row per **UTC** hour (`"YYYY-MM-DDTHH"`), sorted by hour: the number of events, the number of distinct users (an event without a user counts as an event but not a user), and the sum of `order.total` rounded to 2 decimals (missing or not a number counts as 0). A line is bad if it is not JSON, has no `id` or `ts`, or its `ts` has no time zone (`Z` or an offset) or cannot be parsed. An `id` seen before is a retry: skip it (the first copy wins); it is not bad.',
  tests=[['rollup', 'hourly_rollup(' + JL + ')', {'rows': [['2026-10-20T08', 3, 2, 10.6], ['2026-10-20T09', 2, 1, 0], ['2026-10-20T23', 1, 1, 4.25]], 'bad': 4}],
         ['empty', 'hourly_rollup([])', {'rows': [], 'bad': 0}],
         ['a generator, read once', 'def src():\n    yield \'{"id": 1, "ts": "2026-10-20T23:59:59-00:30", "user": "a"}\'\n    yield \'{"id": 2, "ts": "2026-10-21T00:10:00Z", "user": "a", "order": {"total": 2}}\'\nhourly_rollup(src())', {'rows': [['2026-10-21T00', 2, 1, 2]], 'bad': 0}]],
  h=['Per line: parse, validate, convert to UTC, then add to the hour\'s totals. Keep one dict per hour and one set of ids seen.', 'datetime.fromisoformat parses offsets; replace a trailing Z with +00:00 first. A parsed time with tzinfo None has no zone, so it is bad. Then .astimezone(timezone.utc).strftime("%Y-%m-%dT%H").', 'Traps: +05:30 moves the hour back, an offset can move the day, "n/a" is not a number (and True is not a number either), and a retried id must not double count revenue.', 'hours[h] = [events, set_of_users, revenue]\nrows = [[h, n, len(us), round(rev, 2)] for h, (n, us, rev) in sorted(hours.items())]'],
  sol='def hourly_rollup(lines):\n    import json\n    from datetime import datetime, timezone\n    hours, seen, bad = {}, set(), 0\n    for line in lines:\n        try:\n            e = json.loads(line)\n            ts = e["ts"]\n            eid = e["id"]\n            t = datetime.fromisoformat(ts[:-1] + "+00:00" if ts.endswith("Z") else ts)\n            if t.tzinfo is None:\n                raise ValueError("no time zone")\n        except (ValueError, KeyError, TypeError, AttributeError):\n            bad += 1\n            continue\n        if eid in seen:\n            continue\n        seen.add(eid)\n        h = hours.setdefault(t.astimezone(timezone.utc).strftime("%Y-%m-%dT%H"), [0, set(), 0.0])\n        h[0] += 1\n        if e.get("user") is not None:\n            h[1].add(e["user"])\n        total = (e.get("order") or {}).get("total") if isinstance(e.get("order"), dict) else None\n        if isinstance(total, (int, float)) and not isinstance(total, bool):\n            h[2] += total\n    return {"rows": [[k, n, len(us), round(rev, 2)] for k, (n, us, rev) in sorted(hours.items())], "bad": bad}',
  why='Most "process this file" rounds hide three traps in the data: time zones, retries and dirty values. Saying how you treat each is half the score.')

# ---------- Systems 1: distributed systems and storage internals (module d01) ----------
q(m='d01', t='Merge LSM runs with tombstones', lv=M, sig='def merge_runs(runs):\n    pass\n',
  p='An LSM-tree flushes sorted runs (SSTables). Each run is a list of `[key, value, seq]`; a higher `seq` is newer, and `value` None is a **tombstone** (a delete). Compact all runs into one sorted list of `[key, value]` keeping only the newest version of each key and dropping deleted keys.',
  tests=[['newest wins', 'merge_runs([[["a", 1, 1], ["b", 2, 2]], [["a", 9, 5]]])', [['a', 9], ['b', 2]]],
         ['tombstone deletes', 'merge_runs([[["a", 1, 1], ["c", 3, 3]], [["a", None, 7]]])', [['c', 3]]],
         ['older tombstone does not delete a newer write', 'merge_runs([[["k", None, 2]], [["k", "v", 4]]])', [['k', 'v']]],
         ['empty', 'merge_runs([])', []]],
  h=['For each key, only the entry with the highest seq matters.', 'One pass over all entries with a dict from key to (seq, value).', 'Apply the tombstone rule after choosing the newest version, not before.', 'latest = {}\nfor run in runs:\n    for k, v, s in run:\n        if k not in latest or s > latest[k][0]:\n            latest[k] = (s, v)\nreturn [[k, v] for k, (s, v) in sorted(latest.items()) if v is not None]'],
  sol='def merge_runs(runs):\n    latest = {}\n    for run in runs:\n        for k, v, s in run:\n            if k not in latest or s > latest[k][0]:\n                latest[k] = (s, v)\n    return [[k, v] for k, (s, v) in sorted(latest.items()) if v is not None]',
  why='This is compaction in Cassandra, RocksDB and HBase, and the same idea as Iceberg delete files being applied at read or compaction time.')
q(m='d01', t='Consistent hashing ring', lv=M, sig='import bisect\nimport zlib\n\n\ndef h(s):\n    return zlib.crc32(s.encode())\n\n\nclass Ring:\n    def __init__(self, nodes, vnodes=50):\n        pass\n\n    def node_for(self, key):\n        pass\n\n    def add(self, node):\n        pass\n',
  p='Build a consistent hashing ring. Each node gets `vnodes` points on the ring at `h(f"{node}#{i}")` for i in 0..vnodes-1. `node_for(key)` returns the node owning the first point clockwise from `h(key)` (wrap around past the end). `add(node)` adds a node\'s points. Adding a fourth node to three must move only a minority of keys.',
  tests=[['every key maps to a node', 'r = Ring(["a", "b", "c"])\nsorted({r.node_for("k" + str(i)) for i in range(300)})', ['a', 'b', 'c']],
         ['deterministic', 'Ring(["a", "b", "c"]).node_for("trip-42") == Ring(["c", "b", "a"]).node_for("trip-42")', True],
         ['adding a node moves few keys', 'r = Ring(["a", "b", "c"])\nbefore = {i: r.node_for("k" + str(i)) for i in range(1000)}\nr.add("d")\nmoved = [i for i in before if r.node_for("k" + str(i)) != before[i]]\n[len(moved) < 400, all(r.node_for("k" + str(i)) == "d" for i in moved)]', [True, True]]],
  need=[['bisect', 'Use bisect to find the next point on the ring in O(log n).']],
  h=['The ring is a sorted list of (point, node).', 'node_for: find the first point >= h(key) with bisect; if you run off the end, wrap to index 0.', 'Virtual nodes (many points per node) even out the load.', 'i = bisect.bisect_left(self.points, (h(key), ""))\nreturn self.points[i % len(self.points)][1]'],
  sol='import bisect\nimport zlib\n\n\ndef h(s):\n    return zlib.crc32(s.encode())\n\n\nclass Ring:\n    def __init__(self, nodes, vnodes=50):\n        self.vnodes, self.points = vnodes, []\n        for n in nodes:\n            self.add(n)\n\n    def node_for(self, key):\n        i = bisect.bisect_left(self.points, (h(key), ""))\n        return self.points[i % len(self.points)][1]\n\n    def add(self, node):\n        for i in range(self.vnodes):\n            bisect.insort(self.points, (h(f"{node}#{i}"), node))',
  why='Cassandra, DynamoDB and many caches place data this way; "design a distributed cache" expects it.')
q(m='d01', t='Quorum read with read repair', lv=M, sig='def quorum_read(replies, r):\n    pass\n',
  p='`replies` holds one entry per replica: `[version, value]`, or None if that replica is down. Return `[value, stale]` where value comes from the highest version among the replicas that answered, and `stale` lists the indexes of answering replicas that hold an older version (they need read repair). Raise `RuntimeError` if fewer than `r` replicas answered.',
  tests=[['latest wins, stale listed', 'quorum_read([[3, "x"], [5, "y"], None], 2)', ['y', [0]]],
         ['all current', 'quorum_read([[2, "a"], [2, "a"], [2, "a"]], 2)', ['a', []]],
         ['not enough replicas', 'try:\n    quorum_read([None, [1, "a"], None], 2)\n    r = "no error"\nexcept RuntimeError:\n    r = "RuntimeError"\nr', 'RuntimeError']],
  h=['Keep only replicas that answered.', 'Fail fast if fewer than r answered: the read cannot be trusted.', 'The newest version wins; every answering replica with a smaller version is stale.', 'up = [(i, v) for i, v in enumerate(replies) if v is not None]\nif len(up) < r: raise RuntimeError(...)\nbest = max(v[0] for _, v in up)'],
  sol='def quorum_read(replies, r):\n    up = [(i, v) for i, v in enumerate(replies) if v is not None]\n    if len(up) < r:\n        raise RuntimeError("only %d of %d replicas answered" % (len(up), r))\n    best = max(v[0] for _, v in up)\n    value = next(v[1] for _, v in up if v[0] == best)\n    return [value, [i for i, v in up if v[0] < best]]',
  why='Leaderless stores (Cassandra, Dynamo) read from R replicas and repair stale ones; R + W > N is the interview formula behind it.')
q(m='d01', t='Compare vector clocks', lv=M, sig='def compare(a, b):\n    pass\n',
  p='Vector clocks are dicts from node name to counter (a missing node counts as 0). Return `"equal"`, `"before"` (a happened before b: every counter of a <= b and at least one smaller), `"after"`, or `"concurrent"` (neither happened before the other: a conflict to resolve).',
  tests=[['before', 'compare({"a": 1}, {"a": 2, "b": 1})', 'before'], ['after', 'compare({"a": 3, "b": 1}, {"a": 2})', 'after'],
         ['concurrent', 'compare({"a": 2, "b": 0}, {"a": 1, "b": 1})', 'concurrent'], ['equal with missing zero', 'compare({"a": 1, "b": 0}, {"a": 1})', 'equal']],
  h=['Compare node by node over the union of keys, treating missing as 0.', 'Track whether any counter of a is smaller, and whether any is larger.', 'Smaller somewhere and larger somewhere means concurrent.'],
  sol='def compare(a, b):\n    less = more = False\n    for k in set(a) | set(b):\n        x, y = a.get(k, 0), b.get(k, 0)\n        less |= x < y\n        more |= x > y\n    if less and more:\n        return "concurrent"\n    return "before" if less else "after" if more else "equal"',
  why='Causality without synchronised clocks: the basis of conflict detection in multi-leader and leaderless replication.')
q(m='d01', t='Assign Kafka partitions to consumers', lv=M, sig='def range_assign(num_partitions, consumers):\n    pass\n',
  p='Implement Kafka\'s range assignor for one topic: sort the consumer ids, give each `num_partitions // len(consumers)` consecutive partitions, and give one extra partition to each of the first `num_partitions % len(consumers)` consumers. Return a dict from consumer id to its list of partitions. Consumers beyond the partition count get an empty list.',
  tests=[['six over four', 'range_assign(6, ["c4", "c2", "c1", "c3"])', {'c1': [0, 1], 'c2': [2, 3], 'c3': [4], 'c4': [5]}],
         ['more consumers than partitions', 'range_assign(2, ["b", "a", "c"])', {'a': [0], 'b': [1], 'c': []}],
         ['even', 'range_assign(4, ["x", "y"])', {'x': [0, 1], 'y': [2, 3]}]],
  h=['Sort consumers first: assignment must be the same on every member.', 'divmod(num_partitions, len(consumers)) gives the base size and how many get one extra.', 'Walk a running start index, like splitting rows between workers in Python 1\'s level check.'],
  sol='def range_assign(num_partitions, consumers):\n    cs = sorted(consumers)\n    base, extra = divmod(num_partitions, len(cs))\n    out, start = {}, 0\n    for i, c in enumerate(cs):\n        n = base + (1 if i < extra else 0)\n        out[c] = list(range(start, start + n))\n        start += n\n    return out',
  why='One partition is read by at most one consumer in a group, so extra consumers sit idle: the DE 5 consumer-group question, now as code.')

# ---------- A4: LLMs meet the warehouse. Everything runs in your browser: DuckDB in memory, and a fake model in the tests ----------
q(m='a04', t='Guard the SQL a model wrote', lv=M, sig='import re\n\n\ndef safe_sql(sql, allowed, limit=100):\n    pass\n',
  p='A model turned a question into SQL. Before it touches the warehouse, check it. Return `[True, sql]` with the cleaned SQL, or `[False, reason]`.\n\n'
    '1. Strip spaces and one trailing `;`. If a `;` is still inside, reason `"multiple statements"`.\n'
    '2. It must start with `SELECT` or `WITH` (any case), else `"only SELECT"`.\n'
    '3. Any of `insert update delete drop alter create copy attach pragma install load` as a whole word: `"write keyword"`.\n'
    '4. Every table after `FROM` or `JOIN` must be in `allowed` (lower case) or be a CTE name (`name AS (`); else `"table not allowed: name"`.\n'
    '5. No `LIMIT n` at all? Add ` LIMIT {limit}` at the end.',
  tests=[['plain select gets a limit', 'safe_sql("select city, count(*) from trips group by city;", {"trips"})', [True, 'select city, count(*) from trips group by city LIMIT 100']],
         ['existing limit kept', 'safe_sql("SELECT * FROM trips LIMIT 5", {"trips"})', [True, 'SELECT * FROM trips LIMIT 5']],
         ['two statements', 'safe_sql("select 1; drop table trips", {"trips"})', [False, 'multiple statements']],
         ['not a select', 'safe_sql("delete from trips", {"trips"})', [False, 'only SELECT']],
         ['write hidden in a CTE', 'safe_sql("with x as (select 1) insert into trips select * from x", {"trips"})', [False, 'write keyword']],
         ['table outside the allow list', 'safe_sql("select * from trips t join riders r on t.rider_id = r.id", {"trips"})', [False, 'table not allowed: riders']],
         ['CTE names are fine', 'safe_sql("with done as (select * from trips) select count(*) from done", {"trips"})[0]', True]],
  h=['Clean first, then four checks in order, then add the limit.', 're.search(r"\\b(insert|update|...)\\b", sql, re.I) finds a keyword as a whole word.',
     'Tables: re.findall(r"\\b(?:from|join)\\s+([a-zA-Z_][\\w.]*)", sql, re.I). CTE names: re.findall(r"(\\w+)\\s+as\\s*\\(", sql, re.I).',
     'if not re.search(r"\\blimit\\s+\\d+", sql, re.I): sql += " LIMIT " + str(limit)'],
  sol='import re\n\n\ndef safe_sql(sql, allowed, limit=100):\n    sql = sql.strip()\n    if sql.endswith(";"):\n        sql = sql[:-1].strip()\n    if ";" in sql:\n        return [False, "multiple statements"]\n    if not re.match(r"(select|with)\\b", sql, re.I):\n        return [False, "only SELECT"]\n    if re.search(r"\\b(insert|update|delete|drop|alter|create|copy|attach|pragma|install|load)\\b", sql, re.I):\n        return [False, "write keyword"]\n    ctes = {c.lower() for c in re.findall(r"(\\w+)\\s+as\\s*\\(", sql, re.I)}\n    for t in re.findall(r"\\b(?:from|join)\\s+([a-zA-Z_][\\w.]*)", sql, re.I):\n        if t.lower() not in allowed and t.lower() not in ctes:\n            return [False, "table not allowed: " + t.lower()]\n    if not re.search(r"\\blimit\\s+\\d+", sql, re.I):\n        sql += " LIMIT " + str(limit)\n    return [True, sql]',
  why='Never run model-written SQL as is: a read-only check, an allow list and a row limit are the first guardrails of every text-to-SQL and MCP database tool.')
q(m='a04', t='Schema linking: send only the tables that matter', lv=E, sig='import re\n\n\ndef pick_tables(schema, question):\n    pass\n',
  p='`schema` maps table name to its columns, for example `{"trips": ["trip_id", "city", "fare"], "riders": ["rider_id", "tier"]}`. A warehouse has hundreds of tables, so the prompt gets only the ones the question needs.\n\n'
    'Split the question into lower-case words (`re.findall(r"[a-z_]+", q.lower())`). Keep a table if a word equals the table name, the table name without a trailing `s`, or one of its column names. Return the kept names sorted.',
  tests=[['by table name', 'pick_tables({"trips": ["trip_id", "fare"], "riders": ["rider_id", "tier"]}, "How many trips yesterday?")', ['trips']],
         ['singular and a column', 'pick_tables({"trips": ["trip_id", "fare"], "riders": ["rider_id", "tier"]}, "Average fare per rider tier")', ['riders', 'trips']],
         ['nothing matches', 'pick_tables({"trips": ["fare"]}, "hello there")', []]],
  h=['Words of the question against three names per table.', 'Build the set of words once.', 'A table matches on its name, its name.rstrip("s")... careful: only one trailing s.',
     'words = set(re.findall(r"[a-z_]+", question.lower()))\nkeep = [t for t, cols in schema.items() if t in words or (t.endswith("s") and t[:-1] in words) or words & set(cols)]'],
  sol='import re\n\n\ndef pick_tables(schema, question):\n    words = set(re.findall(r"[a-z_]+", question.lower()))\n    keep = [t for t, cols in schema.items() if t in words or (t.endswith("s") and t[:-1] in words) or words & set(cols)]\n    return sorted(keep)',
  why='Text-to-SQL accuracy drops as the schema in the prompt grows: picking the relevant tables first (schema linking) is cheaper and more accurate than sending everything.')
q(m='a04', t='Score text-to-SQL by running it', lv=M, sig='import duckdb\n\n\ndef same_result(con, gold_sql, pred_sql):\n    pass\n',
  p='The fair test of generated SQL is not the text, it is the answer. Run both queries on `con` (a DuckDB connection) and return `True` when they give the same rows, ignoring row order and column names, with floats rounded to 6 places. If `pred_sql` fails, return `False`.',
  tests=[['different SQL, same answer', 'con = duckdb.connect()\ncon.execute("create table t as select * from (values (1, \'Pune\', 10.0), (2, \'Goa\', 20.0), (3, \'Pune\', 5.0)) v(id, city, fare)")\nsame_result(con, "select city, sum(fare) from t group by city", "select city as c, sum(fare) as revenue from t group by 1 order by 1 desc")', True],
         ['wrong filter', 'con = duckdb.connect()\ncon.execute("create table t as select * from (values (1, 10.0), (2, 20.0)) v(id, fare)")\nsame_result(con, "select count(*) from t", "select count(*) from t where fare > 15")', False],
         ['broken SQL', 'con = duckdb.connect()\nsame_result(con, "select 1", "selec 1")', False]],
  h=['Fetch both results, normalise, compare.', 'con.execute(sql).fetchall() gives a list of tuples.', 'Round floats inside each row, then sort the rows.',
     'def norm(rows):\n    return sorted(tuple(round(v, 6) if isinstance(v, float) else v for v in r) for r in rows)'],
  sol='import duckdb\n\n\ndef same_result(con, gold_sql, pred_sql):\n    def norm(rows):\n        return sorted((tuple(round(v, 6) if isinstance(v, float) else v for v in r) for r in rows), key=repr)\n    gold = norm(con.execute(gold_sql).fetchall())\n    try:\n        pred = norm(con.execute(pred_sql).fetchall())\n    except Exception:\n        return False\n    return gold == pred',
  why='Execution accuracy on a gold question set is how text-to-SQL and data agents are evaluated before release and after every model or schema change.')
q(m='a04', t='A text-to-SQL loop that fixes its own errors', lv=M, sig='def ask_sql(question, llm, run, tries=3):\n    pass\n',
  p='`llm(prompt)` returns SQL text; `run(sql)` returns rows or raises. Send the question; if running fails, send a new prompt with the error so the model can fix it. Stop after `tries` attempts.\n\n'
    'Return `{"sql": sql, "rows": rows, "tries": n}` on success, or `{"sql": None, "rows": None, "tries": tries}` when every attempt failed. The retry prompt is the question, a new line, then `"The last SQL failed: "` and the error text.',
  tests=[['fixed on the second try', 'import duckdb\ncon = duckdb.connect()\nanswers = iter(["select count(*) from trip", "select count(*) from range(5)"])\nprompts = []\ndef llm(p):\n    prompts.append(p)\n    return next(answers)\nr = ask_sql("How many?", llm, lambda s: con.execute(s).fetchall())\n[r["rows"], r["tries"], "The last SQL failed: " in prompts[1]]', [[[5]], 2, True]],
         ['gives up', 'def bad(s):\n    raise ValueError("no such table")\nask_sql("q", lambda p: "select x", bad, tries=2)', {'sql': None, 'rows': None, 'tries': 2}],
         ['first try works', 'ask_sql("q", lambda p: "select 1", lambda s: [[1]])["tries"]', 1]],
  h=['A loop with a changing prompt.', 'try: rows = run(sql) ... except Exception as e: build the next prompt from str(e).', 'Return inside the try as soon as it works.',
     'prompt = question\nfor i in range(tries):\n    sql = llm(prompt)\n    try:\n        return {"sql": sql, "rows": run(sql), "tries": i + 1}\n    except Exception as e:\n        prompt = question + "\\nThe last SQL failed: " + str(e)'],
  sol='def ask_sql(question, llm, run, tries=3):\n    prompt = question\n    for i in range(tries):\n        sql = llm(prompt)\n        try:\n            return {"sql": sql, "rows": run(sql), "tries": i + 1}\n        except Exception as e:\n            prompt = question + "\\nThe last SQL failed: " + str(e)\n    return {"sql": None, "rows": None, "tries": tries}',
  why='Feeding the database error back is the cheapest accuracy boost in text-to-SQL; the try cap keeps cost and latency bounded.')
q(m='a04', t='An AI column function with a cache', lv=E, sig='import hashlib\n\n\ndef classify_all(texts, llm, cache):\n    pass\n',
  p='Warehouse AI functions (like `AI_CLASSIFY` in Snowflake or `ai_query` in Databricks) call a model once per row, and you pay per call. Write `classify_all`: return the label for each text in order, calling `llm(text)` only for texts not already in `cache` (a dict keyed by the SHA-256 hex of the text). Store new labels in `cache`.',
  tests=[['labels in order, duplicates called once', 'calls = []\ndef llm(t):\n    calls.append(t)\n    return "late" if "late" in t else "other"\ncache = {}\n[classify_all(["driver late", "great ride", "driver late"], llm, cache), len(calls)]', [['late', 'other', 'late'], 2]],
         ['second run is free', 'calls = []\ndef llm(t):\n    calls.append(t)\n    return "x"\ncache = {}\nclassify_all(["a", "b"], llm, cache)\nclassify_all(["b", "a"], llm, cache)\nlen(calls)', 2]],
  h=['One key per text; call only on a miss.', 'hashlib.sha256(text.encode()).hexdigest()', 'Duplicates inside one batch hit the cache too, if you store as you go.',
     'out = []\nfor t in texts:\n    k = hashlib.sha256(t.encode()).hexdigest()\n    if k not in cache:\n        cache[k] = llm(t)\n    out.append(cache[k])'],
  sol='import hashlib\n\n\ndef classify_all(texts, llm, cache):\n    out = []\n    for t in texts:\n        k = hashlib.sha256(t.encode()).hexdigest()\n        if k not in cache:\n            cache[k] = llm(t)\n        out.append(cache[k])\n    return out',
  why='Caching by input hash makes AI backfills idempotent and cheap to rerun; store the model and prompt version with the label so a change forces a refresh.')
q(m='a04', t='A read-only database tool for an agent (MCP style)', lv=M, sig='import duckdb\n\n\ndef call_tool(con, name, args):\n    pass\n',
  p='An agent reaches your data through tools, the way an MCP server exposes them. Implement three tools on a DuckDB connection, returning plain JSON values:\n\n'
    '- `list_tables`: sorted table names (`select table_name from information_schema.tables`).\n'
    '- `describe_table` with `{"table": name}`: `[[column, type], ...]` in table order, or `{"error": "no such table"}`.\n'
    '- `run_query` with `{"sql": ...}`: rows as lists (at most 50), only if the SQL starts with `select` (any case, after spaces); else `{"error": "read-only"}`. If it fails, `{"error": message}`.\n'
    '- Any other name: `{"error": "unknown tool"}`.',
  tests=[['list', 'con = duckdb.connect()\ncon.execute("create table trips(id int, city varchar)")\ncon.execute("create table riders(id int)")\ncall_tool(con, "list_tables", {})', ['riders', 'trips']],
         ['describe', 'con = duckdb.connect()\ncon.execute("create table trips(id int, city varchar)")\ncall_tool(con, "describe_table", {"table": "trips"})', [['id', 'INTEGER'], ['city', 'VARCHAR']]],
         ['missing table', 'call_tool(duckdb.connect(), "describe_table", {"table": "nope"})', {'error': 'no such table'}],
         ['query', 'con = duckdb.connect()\ncall_tool(con, "run_query", {"sql": "  SELECT 1 + 1"})', [[2]]],
         ['writes refused', 'call_tool(duckdb.connect(), "run_query", {"sql": "drop table trips"})', {'error': 'read-only'}],
         ['unknown', 'call_tool(duckdb.connect(), "delete_everything", {})', {'error': 'unknown tool'}]],
  h=['One branch per tool name; every branch returns plain lists, dicts and strings.', 'information_schema.columns has column_name, data_type and ordinal_position.',
     'For run_query: name.strip().lower().startswith("select"); wrap execute in try/except.', 'rows = con.execute(sql).fetchmany(50)\nreturn [list(r) for r in rows]'],
  sol='import duckdb\n\n\ndef call_tool(con, name, args):\n    if name == "list_tables":\n        return sorted(r[0] for r in con.execute("select table_name from information_schema.tables").fetchall())\n    if name == "describe_table":\n        rows = con.execute("select column_name, data_type from information_schema.columns where table_name = ? order by ordinal_position", [args.get("table")]).fetchall()\n        return [list(r) for r in rows] if rows else {"error": "no such table"}\n    if name == "run_query":\n        sql = args.get("sql", "")\n        if not sql.strip().lower().startswith("select"):\n            return {"error": "read-only"}\n        try:\n            return [list(r) for r in con.execute(sql).fetchmany(50)]\n        except Exception as e:\n            return {"error": str(e)}\n    return {"error": "unknown tool"}',
  why='This is the shape of a database MCP server: discover, describe, query read-only, with a row cap and errors the model can read. Least privilege lives in the tools, not in the prompt.')

# ---------- A5: Vectors, documents and RAG pipelines ----------
q(m='a05', t='Chunk a document with overlap', lv=E, sig='def chunk_words(text, size, overlap):\n    pass\n',
  p='Split `text` into words (`text.split()`) and return chunks of `size` words, each starting `size - overlap` words after the previous one, joined with single spaces. The last chunk ends at the last word; do not add a chunk that only repeats the overlap. Empty text gives `[]`.',
  tests=[['overlap', 'chunk_words("a b c d e f g", 3, 1)', ['a b c', 'c d e', 'e f g']],
         ['short text', 'chunk_words("one two", 5, 2)', ['one two']],
         ['no overlap', 'chunk_words("a b c d", 2, 0)', ['a b', 'c d']],
         ['empty', 'chunk_words("   ", 3, 1)', []]],
  h=['Slide a window of size words by size - overlap.', 'Stop as soon as a window reaches the end.', 'Empty: return [] before the loop.',
     'i = 0\nwhile True:\n    out.append(" ".join(w[i:i + size]))\n    if i + size >= len(w):\n        break\n    i += size - overlap'],
  sol='def chunk_words(text, size, overlap):\n    w = text.split()\n    if not w:\n        return []\n    out, i = [], 0\n    while True:\n        out.append(" ".join(w[i:i + size]))\n        if i + size >= len(w):\n            break\n        i += size - overlap\n    return out',
  why='Chunk size and overlap decide what retrieval can find: too big blurs the meaning, too small loses context across a boundary.')
q(m='a05', t='Embeddings you can see: hashed word vectors', lv=M, sig='import hashlib, math, re\n\n\ndef embed(text, dim=64):\n    pass\n\n\ndef cosine(a, b):\n    pass\n',
  p='Real embeddings come from a model, but the pipeline around them is the same. Build a tiny one that runs anywhere:\n\n'
    '`embed`: lower-case words `re.findall(r"[a-z0-9]+", text.lower())`; each adds 1 at position `int(hashlib.md5(word.encode()).hexdigest(), 16) % dim`; then divide by the vector length (L2 norm). All zeros stays all zeros.\n\n'
    '`cosine(a, b)`: dot product of two normalised vectors (0 if either is all zeros).',
  tests=[['same text', 'round(cosine(embed("kafka consumer lag"), embed("Kafka consumer LAG")), 6)', 1.0],
         ['closer meaning ranks higher', 'q = embed("kafka lag alert")\ncosine(q, embed("consumer lag on kafka topic")) > cosine(q, embed("spark join skew"))', True],
         ['length and norm', 'v = embed("a b c")\n[len(v), round(sum(x * x for x in v), 6)]', [64, 1.0]],
         ['empty', 'sum(embed("!!!"))', 0]],
  h=['Count words into buckets, then normalise.', 'n = math.sqrt(sum(x * x for x in v))', 'cosine of normalised vectors is just sum(x * y).',
     'v = [0.0] * dim\nfor w in re.findall(r"[a-z0-9]+", text.lower()):\n    v[int(hashlib.md5(w.encode()).hexdigest(), 16) % dim] += 1'],
  sol='import hashlib, math, re\n\n\ndef embed(text, dim=64):\n    v = [0.0] * dim\n    for w in re.findall(r"[a-z0-9]+", text.lower()):\n        v[int(hashlib.md5(w.encode()).hexdigest(), 16) % dim] += 1\n    n = math.sqrt(sum(x * x for x in v))\n    return [x / n for x in v] if n else v\n\n\ndef cosine(a, b):\n    return sum(x * y for x, y in zip(a, b))',
  why='Every vector pipeline is embed, normalise, compare. Swap this function for a model call and the rest of the pipeline does not change.')
q(m='a05', t='Vector search inside DuckDB', lv=M, sig='import duckdb\n\n\ndef search(con, qvec, k):\n    pass\n',
  p='Table `chunks(id INTEGER, txt VARCHAR, emb FLOAT[n])` holds embeddings. Return the ids of the `k` chunks most similar to `qvec` (a Python list of n floats), best first, using DuckDB\'s `array_cosine_similarity`. Cast the parameter to the same fixed size: `?::FLOAT[n]` where n is `len(qvec)`.',
  tests=[['nearest first', 'con = duckdb.connect()\ncon.execute("create table chunks(id int, txt varchar, emb float[3])")\ncon.execute("insert into chunks values (1, \'kafka\', [1, 0, 0]), (2, \'spark\', [0, 1, 0]), (3, \'kafka lag\', [0.9, 0.1, 0])")\nsearch(con, [1, 0, 0], 2)', [1, 3]],
         ['k larger than the table', 'con = duckdb.connect()\ncon.execute("create table chunks(id int, txt varchar, emb float[2])")\ncon.execute("insert into chunks values (7, \'a\', [0, 1])")\nsearch(con, [0, 1], 5)', [7]]],
  h=['ORDER BY similarity DESC LIMIT k.', 'Fixed-size arrays need the size in the type: FLOAT[3].', 'Pass qvec and k as parameters, not by gluing strings of numbers.',
     'sql = f"select id from chunks order by array_cosine_similarity(emb, ?::FLOAT[{len(qvec)}]) desc limit ?"'],
  sol='import duckdb\n\n\ndef search(con, qvec, k):\n    sql = f"select id from chunks order by array_cosine_similarity(emb, ?::FLOAT[{len(qvec)}]) desc limit ?"\n    return [r[0] for r in con.execute(sql, [qvec, k]).fetchall()]',
  why='Most teams do not need a separate vector database at first: the warehouse or Postgres (pgvector) can store and rank embeddings next to the rest of the data.')
q(m='a05', t='Keep the index fresh: what to embed and what to delete', lv=E, sig='import hashlib\n\n\ndef plan_index(indexed, docs):\n    pass\n',
  p='`indexed` maps doc id to the SHA-256 hex of the text that is in the vector index now. `docs` maps doc id to the current text in the source. Return `{"embed": [...], "delete": [...]}`: ids that are new or whose text changed, and ids that are in the index but gone from the source. Both sorted.',
  tests=[['new, changed, gone, same', 'import hashlib\nh = lambda t: hashlib.sha256(t.encode()).hexdigest()\nplan_index({"a": h("v1"), "b": h("same"), "c": h("old")}, {"a": "v2", "b": "same", "d": "new"})', {'embed': ['a', 'd'], 'delete': ['c']}],
         ['nothing to do', 'import hashlib\nplan_index({"x": hashlib.sha256(b"t").hexdigest()}, {"x": "t"})', {'embed': [], 'delete': []}]],
  h=['Compare hashes, not texts.', 'New: id not in indexed. Changed: hash differs.', 'Gone: in indexed, not in docs.',
     'embed = sorted(i for i, t in docs.items() if indexed.get(i) != hashlib.sha256(t.encode()).hexdigest())'],
  sol='import hashlib\n\n\ndef plan_index(indexed, docs):\n    embed = sorted(i for i, t in docs.items() if indexed.get(i) != hashlib.sha256(t.encode()).hexdigest())\n    delete = sorted(i for i in indexed if i not in docs)\n    return {"embed": embed, "delete": delete}',
  why='Re-embedding everything every night is the most common RAG cost leak. Hash-based change detection (or CDC from the source) embeds only what changed and removes what was deleted.')
q(m='a05', t='Measure retrieval: recall at k', lv=E, sig='def recall_at_k(results, gold, k):\n    pass\n',
  p='`results` maps each question to the ranked list of chunk ids your search returned. `gold` maps each question to the list of chunk ids that answer it. Recall at k for one question is (relevant ids in the top k) / (number of relevant ids). Return the average over the questions in `gold`, rounded to 3 places. A question missing from `results` scores 0.',
  tests=[['two questions', 'recall_at_k({"q1": [3, 1, 9], "q2": [5, 6]}, {"q1": [1, 2], "q2": [5]}, 2)', 0.75],
         ['missing question', 'recall_at_k({}, {"q": [1]}, 3)', 0.0],
         ['k matters', 'recall_at_k({"q": [9, 8, 1]}, {"q": [1]}, 2)', 0.0]],
  h=['Per question, then average.', 'set(results.get(q, [])[:k]) & set(rel)', 'Divide by len(gold).',
     'scores = [len(set(results.get(q, [])[:k]) & set(rel)) / len(rel) for q, rel in gold.items()]'],
  sol='def recall_at_k(results, gold, k):\n    scores = [len(set(results.get(q, [])[:k]) & set(rel)) / len(rel) for q, rel in gold.items()]\n    return round(sum(scores) / len(scores), 3) if scores else 0.0',
  why='Most bad RAG answers are retrieval misses. Recall at k on a small labelled set tells you whether to fix chunking and search before you touch the prompt.')
q(m='a05', t='LLM extraction as ETL: validate, retry, dead-letter', lv=M, sig='import json, re\n\n\ndef extract_trip(text, llm):\n    pass\n',
  p='Turn a support email into a row. `llm(prompt)` returns a JSON string. Valid means: an object with `city` (non-empty string), `fare` (a number, not a bool) and `date` matching `YYYY-MM-DD`.\n\n'
    'Prompt with `text`. If the reply is invalid, prompt once more with `text`, a new line, and `"Fix: "` plus a short reason. Return `{"ok": True, "data": {"city", "fare", "date"}}` with only those three keys, or after two bad replies `{"ok": False, "error": reason}` (the row goes to a dead-letter table, not the warehouse).',
  tests=[['valid first time', 'extract_trip("Ride in Pune on 2026-10-02 cost 250", lambda p: \'{"city": "Pune", "fare": 250, "date": "2026-10-02", "mood": "ok"}\')', {'ok': True, 'data': {'city': 'Pune', 'fare': 250, 'date': '2026-10-02'}}],
         ['fixed on retry', 'replies = iter([\'not json\', \'{"city": "Goa", "fare": 99.5, "date": "2026-09-30"}\'])\nseen = []\ndef llm(p):\n    seen.append(p)\n    return next(replies)\nr = extract_trip("email", llm)\n[r["ok"], r["data"]["city"], "Fix: " in seen[1]]', [True, 'Goa', True]],
         ['dead letter', 'extract_trip("email", lambda p: \'{"city": "Goa", "fare": "lots", "date": "yesterday"}\')["ok"]', False]],
  h=['A validate function, then at most two tries.', 'json.loads in try/except; isinstance(fare, (int, float)) and not isinstance(fare, bool).', 're.fullmatch(r"\\d{4}-\\d{2}-\\d{2}", date)',
     'def check(s):\n    try:\n        d = json.loads(s)\n    except ValueError:\n        return None, "not JSON"\n    ...'],
  sol='import json, re\n\n\ndef extract_trip(text, llm):\n    def check(s):\n        try:\n            d = json.loads(s)\n        except ValueError:\n            return None, "not JSON"\n        if not isinstance(d, dict):\n            return None, "not an object"\n        if not isinstance(d.get("city"), str) or not d["city"]:\n            return None, "city missing"\n        f = d.get("fare")\n        if not isinstance(f, (int, float)) or isinstance(f, bool):\n            return None, "fare is not a number"\n        if not isinstance(d.get("date"), str) or not re.fullmatch(r"\\d{4}-\\d{2}-\\d{2}", d["date"]):\n            return None, "date is not YYYY-MM-DD"\n        return {"city": d["city"], "fare": f, "date": d["date"]}, None\n    prompt, why = text, ""\n    for _ in range(2):\n        data, why = check(llm(prompt))\n        if data:\n            return {"ok": True, "data": data}\n        prompt = text + "\\nFix: " + why\n    return {"ok": False, "error": why}',
  why='LLM extraction turns unstructured text into tables, but only with a schema check, a bounded retry and a dead-letter path, the same contract as any other ingestion job.')
q(m='a05', t='Redact personal data before it reaches a model', lv=E, sig='import re\n\n\ndef redact(text):\n    pass\n',
  p='Replace email addresses with `[EMAIL]` and phone numbers with `[PHONE]` before text goes into a prompt or a vector index. A phone number here is an optional `+`, then 10 to 13 digits that may be split by single spaces or dashes.',
  tests=[['email', 'redact("Write to asha.k@example.com today")', 'Write to [EMAIL] today'],
         ['phones', 'redact("Call +91 98450 12345 or 080-4123-4567.")', 'Call [PHONE] or [PHONE].'],
         ['short numbers stay', 'redact("Trip 4521 cost 250")', 'Trip 4521 cost 250']],
  h=['Two substitutions; emails first.', 'Email: r"[\\w.+-]+@[\\w-]+(\\.[\\w-]+)+"', 'Phone: a digit, then 9 to 12 more digits each optionally preceded by a space or dash.',
     're.sub(r"\\+?\\d(?:[ -]?\\d){9,12}", "[PHONE]", text)'],
  sol='import re\n\n\ndef redact(text):\n    text = re.sub(r"[\\w.+-]+@[\\w-]+(?:\\.[\\w-]+)+", "[EMAIL]", text)\n    return re.sub(r"\\+?\\d(?:[ -]?\\d){9,12}", "[PHONE]", text)',
  why='Prompts, logs and vector indexes are new places for personal data to leak; redact at ingestion, before the model or the index ever sees it.')

# ---------- Module 1: the walking skeleton, in the browser (minilake: Kafka-, S3- and Airflow-style, no Docker) ----------
q(m='s01', t='Produce trip events, keyed by trip', lv=E, sig='import json\nfrom minilake import Broker\n\n\ndef send_events(broker, events):\n    pass\n',
  p='Create the topic `trip_events` with **3 partitions** (if it does not exist), then send every event with `broker.produce(topic, key, value)`: the key is the event\'s `trip_id`, the value is the event as a JSON string. Return how many you sent.\n\nWhy the key: every event of one trip lands in the same partition, so they stay in order.',
  tests=[['count', 'from minilake import Broker, trip_events\nb = Broker()\nev = trip_events(50)\nsend_events(b, ev) == len(ev) == sum(b.end_offsets("trip_events"))', True],
         ['one trip, one partition, in order', 'from minilake import Broker\nb = Broker()\nsend_events(b, [{"event_id": "e1", "trip_id": "t-1", "n": 1}, {"event_id": "e2", "trip_id": "t-2", "n": 1}, {"event_id": "e3", "trip_id": "t-1", "n": 2}])\np = b.partition_for("trip_events", "t-1")\n[json.loads(v)["n"] for k, v in b.topics["trip_events"][p] if k == "t-1"]', [1, 2]],
         ['three partitions', 'from minilake import Broker\nb = Broker()\nsend_events(b, [])\nlen(b.topics["trip_events"])', 3]],
  h=['Create the topic once, then one produce per event.', 'broker.create_topic("trip_events", partitions=3)', 'json.dumps(e) turns a dict into the JSON string Kafka would carry.', 'for e in events:\n    broker.produce("trip_events", e["trip_id"], json.dumps(e))'],
  sol='import json\nfrom minilake import Broker\n\n\ndef send_events(broker, events):\n    broker.create_topic("trip_events", partitions=3)\n    for e in events:\n        broker.produce("trip_events", e["trip_id"], json.dumps(e))\n    return len(events)',
  why='Partition by the entity key: ordering in Kafka holds only within a partition, so all of one trip\'s events must share one.')
q(m='s01', t='Consume one hour, drop duplicates, commit', lv=M, sig='import json\n\n\ndef read_interval(broker, group, start, end):\n    pass\n',
  p='Read `trip_events` as consumer group `group` (`broker.consumer(group, "trip_events")`, then `poll(100000)`). Parse each value from JSON and keep events with `start <= event_ts < end` (ISO strings compare correctly). The producer sometimes sends an event twice: keep one per `event_id`. Commit the offsets, and return the events sorted by `event_ts`, then `event_id`.',
  tests=[['the 09:00 hour', 'from minilake import Broker, trip_events\nb = Broker(); b.create_topic("trip_events", 3)\nev = trip_events(200)\nfor e in ev: b.produce("trip_events", e["trip_id"], json.dumps(e))\nwant = len({e["event_id"] for e in ev if "2026-10-11T09" <= e["event_ts"] < "2026-10-11T10"})\nlen(read_interval(b, "g", "2026-10-11T09", "2026-10-11T10")) == want', True],
         ['no duplicates', 'from minilake import Broker, trip_events\nb = Broker(); b.create_topic("trip_events", 3)\nfor e in trip_events(300): b.produce("trip_events", e["trip_id"], json.dumps(e))\nr = read_interval(b, "g", "2026-10-11T00", "2026-10-12T00")\nlen(r) == len({e["event_id"] for e in r})', True],
         ['offsets committed: a second read is empty', 'from minilake import Broker, trip_events\nb = Broker(); b.create_topic("trip_events", 3)\nfor e in trip_events(30): b.produce("trip_events", e["trip_id"], json.dumps(e))\nread_interval(b, "g", "2026-10-11T00", "2026-10-12T00")\n[len(read_interval(b, "g", "2026-10-11T00", "2026-10-12T00")), b.lag("g", "trip_events")]', [0, 0]]],
  h=['Poll, parse, filter, dedupe, commit, sort.', 'A dict keyed by event_id keeps one copy of each event.', 'c = broker.consumer(group, "trip_events"); records = c.poll(100000); c.commit()', 'keep = {}\nfor r in records:\n    e = json.loads(r["value"])\n    if start <= e["event_ts"] < end:\n        keep[e["event_id"]] = e'],
  sol='import json\n\n\ndef read_interval(broker, group, start, end):\n    c = broker.consumer(group, "trip_events")\n    keep = {}\n    for r in c.poll(100000):\n        e = json.loads(r["value"])\n        if start <= e["event_ts"] < end:\n            keep[e["event_id"]] = e\n    c.commit()\n    return sorted(keep.values(), key=lambda e: (e["event_ts"], e["event_id"]))',
  why='At-least-once delivery means duplicates: dedupe by a stable event id, and commit offsets only after the work is done.')
q(m='s01', t='Land raw Parquet by hour, safe to rerun', lv=M, sig='from minilake import ObjectStore\n\n\ndef write_raw(store, events):\n    pass\n',
  p='Write the events to the store as Parquet, one file per hour: `s3://lake/raw/trip_events/dt=YYYY-MM-DD/hour=HH/part-0.parquet` (dt is `event_ts[:10]`, hour is `event_ts[11:13]`). Use `store.write_parquet(path, rows)`. Return the sorted list of paths you wrote.\n\n**The incident:** a rerun of the same hour must not double the rows. Writing the whole hour to the same file name replaces it, so a rerun is safe (that is what `mode("overwrite")` per partition does in Spark).',
  tests=[['paths', 'from minilake import ObjectStore\ns = ObjectStore()\nwrite_raw(s, [{"event_id": "a", "event_ts": "2026-10-11T09:10:00Z", "city": "Pune"}, {"event_id": "b", "event_ts": "2026-10-11T10:05:00Z", "city": "Goa"}])', ['s3://lake/raw/trip_events/dt=2026-10-11/hour=09/part-0.parquet', 's3://lake/raw/trip_events/dt=2026-10-11/hour=10/part-0.parquet']],
         ['a rerun does not double rows', 'from minilake import ObjectStore, trip_events\ns = ObjectStore()\nev = [e for e in trip_events(100) if e["event_ts"].startswith("2026-10-11T09")]\nwrite_raw(s, ev); write_raw(s, ev)\ns.duckdb("s3://lake/raw/trip_events/").execute("select count(*) from raw").fetchone()[0] == len(ev)', True],
         ['readable with dt and hour columns', 'from minilake import ObjectStore\ns = ObjectStore()\nwrite_raw(s, [{"event_id": "a", "event_ts": "2026-10-11T09:10:00Z", "city": "Pune"}])\n[list(r) for r in s.duckdb("s3://lake/raw/").execute("select city, cast(hour as int) from raw").fetchall()]', [['Pune', 9]]]],
  h=['Group the events by (dt, hour), then one write per group.', 'key = (e["event_ts"][:10], e["event_ts"][11:13])', 'The same path for the same hour means a rerun overwrites instead of appending.', 'path = "s3://lake/raw/trip_events/dt=%s/hour=%s/part-0.parquet" % key'],
  sol='from minilake import ObjectStore\n\n\ndef write_raw(store, events):\n    groups = {}\n    for e in events:\n        groups.setdefault((e["event_ts"][:10], e["event_ts"][11:13]), []).append(e)\n    paths = []\n    for (dt, hour), rows in groups.items():\n        path = "s3://lake/raw/trip_events/dt=%s/hour=%s/part-0.parquet" % (dt, hour)\n        store.write_parquet(path, rows)\n        paths.append(path)\n    return sorted(paths)',
  why='Idempotent writes (replace the whole partition for the interval) are what make retries and backfills safe: the most common data incident is a rerun that appended.')
q(m='s01', t='Completed trips per city, straight from the lake', lv=E, sig='def completed_per_city(store):\n    pass\n',
  p='`store.duckdb("s3://lake/raw/trip_events/")` gives a DuckDB connection with every file there as the view `raw`. Return `[[city, completed_trips], ...]` sorted by city, where completed trips is the number of **distinct** `trip_id` with `event_type = \'completed\'`.',
  tests=[['two cities', 'from minilake import ObjectStore\ns = ObjectStore()\ns.write_parquet("s3://lake/raw/trip_events/dt=2026-10-11/hour=09/part-0.parquet", [{"trip_id": "t1", "event_type": "completed", "city": "Pune"}, {"trip_id": "t1", "event_type": "completed", "city": "Pune"}, {"trip_id": "t2", "event_type": "cancelled", "city": "Pune"}, {"trip_id": "t3", "event_type": "completed", "city": "Goa"}])\ncompleted_per_city(s)', [['Goa', 1], ['Pune', 1]]]],
  h=['One GROUP BY query.', 'count(distinct trip_id) counts each trip once even if its event arrived twice.', 'Return lists, not tuples: [list(r) for r in rows].', 'select city, count(distinct trip_id) from raw where event_type = \'completed\' group by city order by city'],
  sol='def completed_per_city(store):\n    con = store.duckdb("s3://lake/raw/trip_events/")\n    rows = con.execute("select city, count(distinct trip_id) from raw where event_type = \'completed\' group by city order by city").fetchall()\n    return [list(r) for r in rows]',
  why='The serving query of the skeleton: counting distinct business keys protects the answer from duplicate events.')
q(m='s01', t='An hourly DAG with a data quality gate', lv=M, sig='from minilake import Dag\n\n\ndef build_dag(rows_for):\n    pass\n',
  p='`rows_for(start, end)` returns the rows for an interval. Build a `Dag("trip_events_hourly")` with three tasks in a chain:\n\n1. `extract`: returns `rows_for(ctx["data_interval_start"], ctx["data_interval_end"])`.\n2. `check`: raises `ValueError("no rows")` when extract returned nothing (read it from `ctx["results"]["extract"]`).\n3. `count`: returns the number of rows.\n\nUse the **data interval** from the context, never "now", so reruns and backfills process the right hour. Return the dag.',
  tests=[['a good hour', 'import datetime as dt\nd = build_dag(lambda s, e: [1, 2, 3] if s.hour == 9 else [])\nr = d.run(dt.datetime(2026, 10, 11, 9), dt.datetime(2026, 10, 11, 10))\n[r["ok"], r["results"]["count"]]', [True, 3]],
         ['an empty hour stops at the gate', 'import datetime as dt\nd = build_dag(lambda s, e: [])\nd.run(dt.datetime(2026, 10, 11, 3), dt.datetime(2026, 10, 11, 4))["state"]', {'extract': 'success', 'check': 'failed', 'count': 'upstream_failed'}],
         ['backfill uses each interval', 'import datetime as dt\nd = build_dag(lambda s, e: [s.hour] * s.hour)\n[r["results"].get("count") for r in d.backfill(dt.datetime(2026, 10, 11, 1), dt.datetime(2026, 10, 11, 4))]', [1, 2, 3]]],
  h=['Three d.task(...) calls; the second and third name the one before in after=.', 'Each task is a function of ctx.', 'def check(ctx):\n    if not ctx["results"]["extract"]:\n        raise ValueError("no rows")', 'd = Dag("trip_events_hourly")\nd.task("extract", lambda ctx: rows_for(ctx["data_interval_start"], ctx["data_interval_end"]))'],
  sol='from minilake import Dag\n\n\ndef build_dag(rows_for):\n    d = Dag("trip_events_hourly")\n    d.task("extract", lambda ctx: rows_for(ctx["data_interval_start"], ctx["data_interval_end"]))\n\n    def check(ctx):\n        if not ctx["results"]["extract"]:\n            raise ValueError("no rows")\n    d.task("check", check, after=["extract"])\n    d.task("count", lambda ctx: len(ctx["results"]["extract"]), after=["check"])\n    return d',
  why='Interviewers ask about data intervals because backfills only work when tasks read the interval they are given; a quality gate stops bad hours before anyone queries them.')

# ---------- Module 2: an Iceberg-style table, in the browser (minilake Table: snapshots, files metadata, column ids) ----------
q(m='s02', t='MERGE INTO on event_id: a rerun adds nothing', lv=M, sig='def merge_events(table, events):\n    pass\n',
  p='`table` is a `minilake.Table`, partitioned by the day of `event_ts`. Write the ingest step the way `MERGE INTO ... ON event_id` works:\n\n'
    '1. Inside the batch, keep one event per `event_id` (the last one wins): the generator sends about 1% twice.\n'
    '2. For each day the batch touches, read that day\'s current rows with `table.scan(day=d)` (`table.day_of(e)` gives an event\'s day), and upsert the batch\'s events by `event_id`.\n'
    '3. Commit once, replacing only the touched days\' files: `table.commit(add_rows=rows, delete_files=[f for f in table.files() if f["partition"] in days], base=table.current)`.\n\n'
    'Return the number of `event_id`s that are new to the table. Running the same hour twice must leave the row count unchanged.',
  tests=[['a rerun adds no rows', 'from minilake import ObjectStore, Table, trip_events\nCOLS = ["event_id", "event_type", "trip_id", "city", "fare_amount", "event_ts"]\nt = Table(ObjectStore(), "s3://lake/trips", COLS)\nev = trip_events(120)\na = merge_events(t, ev); n = len(t.scan()); b = merge_events(t, ev)\n[a == len({e["event_id"] for e in ev}), n == len(t.scan()) == a, b]', [True, True, 0]],
         ['a changed event replaces the old row', 'from minilake import ObjectStore, Table, trip_events\nCOLS = ["event_id", "event_type", "trip_id", "city", "fare_amount", "event_ts"]\nt = Table(ObjectStore(), "s3://lake/trips", COLS)\nev = trip_events(30)\nmerge_events(t, ev)\nx = dict(ev[0]); x["fare_amount"] = 1.5\n[merge_events(t, [x]), [r["fare_amount"] for r in t.scan() if r["event_id"] == x["event_id"]]]', [0, [1.5]]],
         ['only the touched day is rewritten', 'from minilake import ObjectStore, Table, trip_events\nCOLS = ["event_id", "event_type", "trip_id", "city", "fare_amount", "event_ts"]\nt = Table(ObjectStore(), "s3://lake/trips", COLS)\nmerge_events(t, trip_events(20, hour="2026-10-10T09")); merge_events(t, trip_events(20, hour="2026-10-11T09"))\nday10 = [f["path"] for f in t.files() if f["partition"] == "2026-10-10"]\nmerge_events(t, trip_events(5, seed=3, hour="2026-10-11T10"))\n[f["path"] for f in t.files() if f["partition"] == "2026-10-10"] == day10', True]],
  h=['A dict keyed by event_id removes duplicates: later events overwrite earlier ones.', 'days = {table.day_of(e) for e in batch}; current = {r["event_id"]: r for d in days for r in table.scan(day=d)}', 'New ids are the batch ids not already in current.', 'table.commit(add_rows=list(current.values()), delete_files=[f for f in table.files() if f["partition"] in days], base=table.current)'],
  sol='def merge_events(table, events):\n    batch = {}\n    for e in events:\n        batch[e["event_id"]] = e\n    days = {table.day_of(e) for e in batch.values()}\n    current = {r["event_id"]: r for d in days for r in table.scan(day=d)}\n    new = len([k for k in batch if k not in current])\n    current.update(batch)\n    table.commit(add_rows=list(current.values()), delete_files=[f for f in table.files() if f["partition"] in days], base=table.current)\n    return new',
  why='Partition overwrite fixes reruns but not duplicate deliveries inside a batch; a MERGE on the event key fixes both, and a table format makes the swap of files one atomic commit.')
q(m='s02', t='Look inside the table: files per day and time travel', lv=E, sig='def inspect(table, as_of):\n    pass\n',
  p='Use only the table\'s metadata, the way you query `.files` and `.snapshots` in Trino:\n\n'
    '- `table.files()` lists the current data files: each has `partition` (the day), `record_count` and `path`.\n'
    '- `table.snapshot_as_of(as_of)` gives the snapshot id that was current at time `as_of`; `table.scan(snapshot_id=...)` reads that snapshot.\n\n'
    'Return `{"files": {day: [number_of_files, average_records_per_file]}, "rows_then": rows in the table as of as_of}`. The average is a whole number (round down).',
  tests=[['files per day', 'from minilake import ObjectStore, Table, trip_events\nCOLS = ["event_id", "event_type", "trip_id", "city", "fare_amount", "event_ts"]\nt = Table(ObjectStore(), "s3://lake/trips", COLS)\nfor h in ("09", "10", "11"): t.append(trip_events(10, seed=int(h), hour="2026-10-11T" + h))\nt.append(trip_events(7, hour="2026-10-12T09"))\ninspect(t, 1)["files"]', {'2026-10-11': [3, 11], '2026-10-12': [1, 8]}],
         ['time travel to before the backfill', 'from minilake import ObjectStore, Table, trip_events\nCOLS = ["event_id", "event_type", "trip_id", "city", "fare_amount", "event_ts"]\nt = Table(ObjectStore(), "s3://lake/trips", COLS)\nt.append(trip_events(10)); first = t.current\nfor d in range(1, 4): t.append(trip_events(10, seed=d, hour="2026-10-0%dT09" % d))\n[inspect(t, first)["rows_then"], len(t.scan())]', [11, 44]]],
  h=['Group table.files() by f["partition"].', 'The average is sum of record_count // number of files.', 'sid = table.snapshot_as_of(as_of); len(table.scan(snapshot_id=sid))', 'out = {}\nfor f in table.files():\n    out.setdefault(f["partition"], []).append(f["record_count"])'],
  sol='def inspect(table, as_of):\n    by = {}\n    for f in table.files():\n        by.setdefault(f["partition"], []).append(f["record_count"])\n    sid = table.snapshot_as_of(as_of)\n    return {"files": {d: [len(v), sum(v) // len(v)] for d, v in sorted(by.items())}, "rows_then": len(table.scan(snapshot_id=sid)) if sid else 0}',
  why='A query engine plans from this metadata (file counts, sizes, partitions) without listing storage, and time travel is reading an older snapshot\'s file list.')
q(m='s02', t='Ten thousand tiny files: compact each day', lv=M, sig='def compact(table, max_files=1):\n    pass\n',
  p='After 48 hourly runs each day has 48 small files and the Finance query crawls. Write `rewrite_data_files`: for every day with more than `max_files` files, read the day (`table.scan(day=d)`) and commit its rows as one new file in place of the old ones (`table.commit(add_rows=..., delete_files=..., base=table.current, operation="replace")`). One commit per day is fine.\n\n'
    'Return the number of files removed. The row count must not change, and an older snapshot must still read until snapshots are expired.',
  tests=[['48 files become 1', 'from minilake import ObjectStore, Table, trip_events\nCOLS = ["event_id", "event_type", "trip_id", "city", "fare_amount", "event_ts"]\nt = Table(ObjectStore(), "s3://lake/trips", COLS)\nfor h in range(24): t.append(trip_events(5, seed=h, hour="2026-10-11T%02d" % h)); t.append(trip_events(5, seed=100 + h, hour="2026-10-11T%02d" % h))\nn = len(t.scan())\n[compact(t), len(t.files()), len(t.scan()) == n]', [47, 1, True]],
         ['old snapshots still read until expiry', 'from minilake import ObjectStore, Table, trip_events\nCOLS = ["event_id", "event_type", "trip_id", "city", "fare_amount", "event_ts"]\ns = ObjectStore(); t = Table(s, "s3://lake/trips", COLS)\nfor h in range(6): t.append(trip_events(4, seed=h, hour="2026-10-11T%02d" % h))\nold = t.current\ncompact(t)\nthen = len(t.scan(snapshot_id=old))\nt.expire_snapshots(keep_last=1)\n[then, len(s.list("s3://lake/trips/data/"))]', [30, 1]],
         ['a day with one file is left alone', 'from minilake import ObjectStore, Table, trip_events\nCOLS = ["event_id", "event_type", "trip_id", "city", "fare_amount", "event_ts"]\nt = Table(ObjectStore(), "s3://lake/trips", COLS)\nt.append(trip_events(5, hour="2026-10-12T09"))\n[compact(t), t.snapshots()[-1]["operation"]]', [0, 'append']]],
  h=['Group table.files() by partition and keep the days with too many files.', 'rows = table.scan(day=d) reads one day.', 'table.commit(add_rows=rows, delete_files=files, base=table.current, operation="replace")', 'removed += len(files) - 1'],
  sol='def compact(table, max_files=1):\n    by = {}\n    for f in table.files():\n        by.setdefault(f["partition"], []).append(f)\n    removed = 0\n    for d, fs in sorted(by.items()):\n        if len(fs) > max_files:\n            table.commit(add_rows=table.scan(day=d), delete_files=fs, base=table.current, operation="replace")\n            removed += len(fs) - 1\n    return removed',
  why='Small files cost a request and a footer read each; compaction rewrites them without changing the data, and old files stay until snapshot expiry so running readers and time travel keep working.')
q(m='s02', t='A renamed column: old files read fine, the report breaks', lv=E, sig='def finance_view(rows, renames):\n    pass\n',
  p='A teammate ran `table.rename_column("fare_amount", "fare")`. The table is fine: files store column ids, so old files now read as `fare`. But the Finance report still asks for `fare_amount` and fails.\n\n'
    'During the migration, publish a view that exposes both names. `renames` maps the new name to the old one, like `{"fare": "fare_amount"}`. Return new row dicts that have every column plus each old name as an alias of the new one. Do not change the input rows.',
  tests=[['old files read under the new name, no file rewritten', 'from minilake import ObjectStore, Table, trip_events\nCOLS = ["event_id", "event_type", "trip_id", "city", "fare_amount", "event_ts"]\nt = Table(ObjectStore(), "s3://lake/trips", COLS)\nt.append(trip_events(10)); paths = [f["path"] for f in t.files()]\nt.rename_column("fare_amount", "fare")\n["fare" in t.scan()[0], "fare_amount" in t.scan()[0], [f["path"] for f in t.files()] == paths]', [True, False, True]],
         ['the report works through the view', 'rows = [{"city": "Pune", "fare": 100.0}, {"city": "Pune", "fare": 50.0}]\nv = finance_view(rows, {"fare": "fare_amount"})\n[sum(r["fare_amount"] for r in v), sum(r["fare"] for r in v), "fare_amount" in rows[0]]', [150.0, 150.0, False]]],
  h=['Copy each row with dict(r) so the input is unchanged.', 'For each new, old in renames.items(): copy[old] = copy[new].', 'Skip a rename whose new column is missing in a row.', 'return [dict(r, **{old: r[new] for new, old in renames.items() if new in r}) for r in rows]'],
  sol='def finance_view(rows, renames):\n    return [dict(r, **{old: r[new] for new, old in renames.items() if new in r}) for r in rows]',
  why='A table format makes a rename safe for the files (columns are tracked by id); the people and queries that use the old name need a migration period, a view or a data contract.')
# ---------- Module 3: Spark under load, in the browser (minilake MiniCluster: shuffle tasks, spill, OOM, a Spark event log) ----------
q(m='s03', t='Read the plan: shuffles, join strategies, pushed filters', lv=E, sig='def read_plan(plan):\n    pass\n',
  p='`plan` is the text of `explain("formatted")` for the enrichment job (trips joined to drivers and zones). Read it the way you would before touching any setting:\n\n'
    '- `shuffles`: how many `Exchange hashpartitioning` operators (each one moves every row across the network).\n'
    '- `broadcasts`: how many `BroadcastExchange` operators.\n'
    '- `joins`: the join operators from top to bottom, by name (`SortMergeJoin`, `BroadcastHashJoin`, `ShuffledHashJoin`).\n'
    '- `pushed`: the filters inside every `PushedFilters: [...]`, each once, in the order they first appear.\n\n'
    'Return a dict with those four keys.',
  tests=[['the plan as written', 'from minilake import MiniCluster, trips_for_join, enrich_plan, hash_partition\nread_plan(enrich_plan())', {'shuffles': 4, 'broadcasts': 0, 'joins': ['SortMergeJoin', 'SortMergeJoin'], 'pushed': ['EqualTo(status,completed)', 'IsNotNull(driver_id)']}],
         ['zones broadcast: two shuffles fewer', 'from minilake import MiniCluster, trips_for_join, enrich_plan, hash_partition\nr = read_plan(enrich_plan(broadcast_zones=True))\n[r["shuffles"], r["broadcasts"], r["joins"]]', [2, 1, ['BroadcastHashJoin', 'SortMergeJoin']]],
         ['the filter was not pushed to the scan', 'from minilake import MiniCluster, trips_for_join, enrich_plan, hash_partition\nread_plan(enrich_plan(filter_first=False))["pushed"]', ['IsNotNull(driver_id)']]],
  h=['Walk the lines once; "Exchange hashpartitioning" in a line is one shuffle.', 'A join name is the first word after "- " on its line: line.split("- ", 1)[1].split()[0].', 'Filters sit between "PushedFilters: [" and "]", separated by ", ".', 'import re\nfor f in re.findall(r"PushedFilters: \\[([^\\]]*)\\]", plan): ...'],
  sol='import re\n\n\ndef read_plan(plan):\n    joins, pushed = [], []\n    for line in plan.splitlines():\n        op = line.split("- ", 1)[1].split()[0] if "- " in line else ""\n        if op.endswith("Join"):\n            joins.append(op)\n    for group in re.findall(r"PushedFilters: \\[([^\\]]*)\\]", plan):\n        for f in [x.strip() for x in group.split(", ") if x.strip()]:\n            if f not in pushed:\n                pushed.append(f)\n    return {"shuffles": plan.count("Exchange hashpartitioning"), "broadcasts": plan.count("BroadcastExchange"), "joins": joins, "pushed": pushed}',
  why='Counting Exchanges and naming each join strategy is how you predict a job\'s cost before running it; "I removed one shuffle by broadcasting zones" is the senior answer.')
q(m='s03', t='Read the event log: the stage summary from 3.9', lv=M, sig='import json, statistics\nfrom collections import defaultdict\n\n\ndef stage_summary(event_log_path, top=5):\n    pass\n',
  p='Write the agent tool from section 3.9. `event_log_path` is a Spark event log: one JSON object per line. Use only `SparkListenerTaskEnd` events: a task\'s seconds are `(Task Info.Finish Time - Task Info.Launch Time) / 1000`, its shuffle read is `Remote Bytes Read + Local Bytes Read` (under `Task Metrics`, `Shuffle Read Metrics`), and its spill is `Task Metrics.Disk Bytes Spilled`.\n\n'
    'Return the `top` stages with the longest task first, each as `{"stage", "tasks", "median_task_s", "max_task_s", "max_shuffle_read_mb", "total_spill_mb"}` (seconds and MB rounded to 1 decimal; 1 MB = 1e6 bytes).',
  tests=[['the skewed join stage comes first', 'from minilake import MiniCluster, trips_for_join, enrich_plan, hash_partition\nT, Z = trips_for_join(hot_share=0.8)\nr = stage_summary(MiniCluster().run_join(T, Z, "zone_id")["log"], top=2)\n[len(r), r[0]["stage"], r[0]["max_task_s"] > 50 * r[0]["median_task_s"], r[0]["total_spill_mb"] > 0]', [2, 2, True, True]],
         ['a healthy run shows no skew', 'from minilake import MiniCluster, trips_for_join, enrich_plan, hash_partition\nT, Z = trips_for_join()\nr = stage_summary(MiniCluster().run_join(T, Z, "zone_id", shuffle_partitions=50)["log"])\n[all(x["max_task_s"] < 3 * x["median_task_s"] for x in r), sum(x["total_spill_mb"] for x in r)]', [True, 0.0]],
         ['every stage is counted', 'from minilake import MiniCluster, trips_for_join, enrich_plan, hash_partition\nT, Z = trips_for_join(10000)\nsorted(x["stage"] for x in stage_summary(MiniCluster().run_join(T, Z, "zone_id", shuffle_partitions=50)["log"]))', [0, 1, 2]]],
  h=['Group tasks by e["Stage ID"] in a defaultdict(list).', 'Skip any line whose "Event" is not SparkListenerTaskEnd.', 'statistics.median(secs) and max(secs) side by side is the skew signature.', 'return sorted(rows, key=lambda r: -r["max_task_s"])[:top]'],
  sol='import json, statistics\nfrom collections import defaultdict\n\n\ndef stage_summary(event_log_path, top=5):\n    tasks = defaultdict(list)\n    with open(event_log_path) as f:\n        for line in f:\n            e = json.loads(line)\n            if e.get("Event") != "SparkListenerTaskEnd":\n                continue\n            info, m = e.get("Task Info", {}), e.get("Task Metrics") or {}\n            read = m.get("Shuffle Read Metrics", {})\n            tasks[e.get("Stage ID")].append({"secs": (info.get("Finish Time", 0) - info.get("Launch Time", 0)) / 1000, "shuffle_mb": (read.get("Remote Bytes Read", 0) + read.get("Local Bytes Read", 0)) / 1e6, "spill_mb": m.get("Disk Bytes Spilled", 0) / 1e6})\n    rows = []\n    for stage, ts in tasks.items():\n        secs = [t["secs"] for t in ts]\n        rows.append({"stage": stage, "tasks": len(ts), "median_task_s": round(statistics.median(secs), 1), "max_task_s": round(max(secs), 1), "max_shuffle_read_mb": round(max(t["shuffle_mb"] for t in ts), 1), "total_spill_mb": round(sum(t["spill_mb"] for t in ts), 1)})\n    return sorted(rows, key=lambda r: -r["max_task_s"])[:top]',
  why='Code does the counting and the model does the reasoning: a five-row summary with the median and maximum side by side is what an agent (and an interviewer) can reason about, not megabytes of JSON.')
q(m='s03', t='One city has 80% of the rows: find the hot key', lv=E, sig='import statistics\nfrom minilake import hash_partition\n\n\ndef skew_report(rows, key, n=200, top=3):\n    pass\n',
  p='The nightly join now fails with an out-of-memory error. Before changing anything, find the cause. `rows` are the trips, `key` the join column and `n` the shuffle partitions. Return:\n\n'
    '- `null_rows`: rows whose key is None (they all land in one partition and match nothing).\n'
    '- `hot`: the `top` most common non-null keys as `[key, rows]`, most rows first (ties: smaller key first).\n'
    '- `max_partition` and `median_partition`: rows per shuffle partition, using `hash_partition(value, n)` for every row (NULLs included), so you see what the tasks see.\n'
    '- `skewed`: True when the largest partition is more than 5 times the median (the adaptive skew-join rule).',
  tests=[['the hot city and the NULLs', 'from minilake import MiniCluster, trips_for_join, enrich_plan, hash_partition\nT, Z = trips_for_join(hot_share=0.8, null_share=0.05)\nr = skew_report(T, "zone_id")\n[2000 < r["null_rows"] < 3000, r["hot"][0][0], r["hot"][0][1] > 35000, r["skewed"]]', [True, 1, True, True]],
         ['a healthy day is not skewed', 'from minilake import MiniCluster, trips_for_join, enrich_plan, hash_partition\nT, Z = trips_for_join()\nr = skew_report(T, "zone_id", n=50)\n[r["null_rows"], len(r["hot"]), r["skewed"]]', [0, 3, False]],
         ['partition counts follow the hash', 'skew_report([{"k": "a"}, {"k": "a"}, {"k": None}, {"k": "b"}], "k", n=1)', {'null_rows': 1, 'hot': [['a', 2], ['b', 1]], 'max_partition': 4, 'median_partition': 4, 'skewed': False}]],
  h=['Count keys with a dict; keep None apart.', 'sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))[:top]', 'sizes = [0] * n; for r in rows: sizes[hash_partition(r[key], n)] += 1', 'statistics.median(sizes) is the median partition.'],
  sol='import statistics\nfrom minilake import hash_partition\n\n\ndef skew_report(rows, key, n=200, top=3):\n    counts, nulls, sizes = {}, 0, [0] * n\n    for r in rows:\n        k = r.get(key)\n        sizes[hash_partition(k, n)] += 1\n        if k is None:\n            nulls += 1\n        else:\n            counts[k] = counts.get(k, 0) + 1\n    med = statistics.median(sizes)\n    return {"null_rows": nulls, "hot": [[k, v] for k, v in sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))[:top]], "max_partition": max(sizes), "median_partition": med, "skewed": max(sizes) > 5 * med}',
  why='"groupBy(key).count() ordered by count" plus the task-size spread is how you prove skew; naming the hot key and the NULLs comes before any fix.')
q(m='s03', t='Fix it: drop the NULLs, then salt the hot key', lv=M, sig='def salt(big, small, key, hot, n=16):\n    pass\n',
  p='Adaptive execution is off and the join must finish. Prepare both sides for `MiniCluster().run_join(big2, small2, "_k")`:\n\n'
    '1. **Drop what cannot match:** big rows whose `key` is None.\n'
    '2. **Salt only the hot keys** (`hot` is a list of key values): the i-th remaining big row with a hot key gets salt `i % n`; every other row gets salt 0. Put `"<key value>#<salt>"` in a new `_k` column.\n'
    '3. **Replicate the small side** for hot keys only: one copy per salt value 0 to n-1, each with its `_k`; other small rows once, with salt 0.\n\n'
    'Return `(big2, small2)`. Do not change the input rows. The join must return the same rows as before, and no task may run out of memory.',
  tests=[['the job finishes with the same rows', 'from minilake import MiniCluster, trips_for_join, enrich_plan, hash_partition\nT, Z = trips_for_join(hot_share=0.8, null_share=0.05)\nc = MiniCluster()\nwant = len([t for t in T if t["zone_id"] is not None])\nb, s = salt(T, Z, "zone_id", [1])\nr = c.run_join(b, s, "_k")\n[c.run_join(T, Z, "zone_id")["failed"], r["failed"], r["rows"] == want, r["max_task_s"] < 30]', [True, False, True, True]],
         ['only the hot key is replicated', 'from minilake import MiniCluster, trips_for_join, enrich_plan, hash_partition\nT, Z = trips_for_join(2000, hot_share=0.5)\nb, s = salt(T, Z, "zone_id", [1], n=8)\n[len(s), sorted(x["_k"] for x in s if x["zone_id"] == 1)[:3], "_k" in Z[0]]', [207, ['1#0', '1#1', '1#2'], False]],
         ['salts spread the hot rows', 'b, s = salt([{"z": 1}, {"z": 1}, {"z": 1}, {"z": 2}, {"z": None}], [{"z": 1}, {"z": 2}], "z", [1], n=2)\n[[x["_k"] for x in b], [x["_k"] for x in s]]', [['1#0', '1#1', '1#0', '2#0'], ['1#0', '1#1', '2#0']]]],
  h=['Filter out None keys first, then number the rows that remain.', 'dict(r, _k="%s#%d" % (r[key], salt)) copies a row with the new column.', 'For the small side: n copies for a hot key, one copy with salt 0 otherwise.', 'i = 0\nfor r in rows:\n    s = i % n if r[key] in hot else 0\n    i += 1'],
  sol='def salt(big, small, key, hot, n=16):\n    hot = set(hot)\n    big2 = []\n    for i, r in enumerate([r for r in big if r.get(key) is not None]):\n        s = i % n if r[key] in hot else 0\n        big2.append(dict(r, _k="%s#%d" % (r[key], s)))\n    small2 = []\n    for r in small:\n        for s in (range(n) if r.get(key) in hot else [0]):\n            small2.append(dict(r, _k="%s#%d" % (r.get(key), s)))\n    return big2, small2',
  why='Filtering NULLs removes rows that could never match; salting spreads one key over n tasks at the cost of an n-times larger small side, so salt only the hot keys and pick n from the measured skew.')

# ---------- Module 5: real time, in the browser (minilake broker; the Spark and Kafka behaviour that interviews ask about) ----------
q(m='s05', t='Demand per minute and zone, with a watermark', lv=M, sig='import datetime as dt\n\n\ndef window_counts(events, watermark_s=120):\n    pass\n',
  p='Events arrive in the order given (not in time order). Each has `event_id`, `event_type`, `zone_id` and `event_ts` (ISO, ending in `Z`). Count `requested` events per one-minute window and zone, the way Structured Streaming does with a watermark:\n\n'
    '- Keep the largest `event_ts` seen so far. An event older than that minus `watermark_s` seconds is **late**: drop it and count it in `late`.\n'
    '- An `event_id` seen before is a duplicate: drop it.\n\n'
    'Return `{"counts": [[window_start, zone_id, n], ...], "late": n}`, counts sorted by window then zone, window_start like `2026-10-11T09:41:00Z`.',
  tests=[['counts per window', 'window_counts([{"event_id": "a", "event_type": "requested", "zone_id": 1, "event_ts": "2026-10-11T09:41:10Z"}, {"event_id": "b", "event_type": "requested", "zone_id": 1, "event_ts": "2026-10-11T09:41:50Z"}, {"event_id": "c", "event_type": "completed", "zone_id": 1, "event_ts": "2026-10-11T09:41:55Z"}, {"event_id": "d", "event_type": "requested", "zone_id": 2, "event_ts": "2026-10-11T09:42:01Z"}])', {'counts': [['2026-10-11T09:41:00Z', 1, 2], ['2026-10-11T09:42:00Z', 2, 1]], 'late': 0}],
         ['late and duplicate events dropped', 'window_counts([{"event_id": "a", "event_type": "requested", "zone_id": 1, "event_ts": "2026-10-11T09:50:00Z"}, {"event_id": "b", "event_type": "requested", "zone_id": 1, "event_ts": "2026-10-11T09:47:00Z"}, {"event_id": "c", "event_type": "requested", "zone_id": 1, "event_ts": "2026-10-11T09:49:00Z"}, {"event_id": "a", "event_type": "requested", "zone_id": 1, "event_ts": "2026-10-11T09:50:00Z"}])', {'counts': [['2026-10-11T09:49:00Z', 1, 1], ['2026-10-11T09:50:00Z', 1, 1]], 'late': 1}]],
  h=['Walk the events once, keeping the max event time and the ids you have seen.', 'dt.datetime.fromisoformat(ts.replace("Z", "+00:00")) parses the time.', 'A window start is the time with seconds set to zero.', 'if t < max_seen - dt.timedelta(seconds=watermark_s):\n    late += 1\n    continue'],
  sol='import datetime as dt\n\n\ndef window_counts(events, watermark_s=120):\n    seen, counts, late, max_seen = set(), {}, 0, None\n    for e in events:\n        t = dt.datetime.fromisoformat(e["event_ts"].replace("Z", "+00:00"))\n        max_seen = t if max_seen is None or t > max_seen else max_seen\n        if t < max_seen - dt.timedelta(seconds=watermark_s):\n            late += 1\n            continue\n        if e["event_id"] in seen:\n            continue\n        seen.add(e["event_id"])\n        if e["event_type"] != "requested":\n            continue\n        w = t.replace(second=0, microsecond=0).strftime("%Y-%m-%dT%H:%M:%SZ")\n        counts[(w, e["zone_id"])] = counts.get((w, e["zone_id"]), 0) + 1\n    return {"counts": [[w, z, n] for (w, z), n in sorted(counts.items())], "late": late}',
  why='A watermark is how a stream decides a window is complete and how much state it may forget; duplicates within it must be dropped by id.')
q(m='s05', t='Exactly-once after a crash: offsets live with the results', lv=M, sig='import json\n\n\ndef run_batch(broker, sink, crash_before_commit=False):\n    pass\n',
  p='`sink` is a dict that stands for your table: `sink["counts"]` maps a zone (string) to a count of `requested` events, and `sink["offsets"]` maps a partition to the next offset to read. Write one micro-batch:\n\n'
    '1. Make a consumer: `c = broker.consumer("demand", "trip_events")`, then **start from the sink\'s offsets**, not Kafka\'s: `c.seek(p, sink["offsets"].get(p, 0))` for each `p` in `c.partitions`.\n'
    '2. `c.poll(100000)`, parse each value as JSON, add 1 to `sink["counts"][str(zone_id)]` for each `requested` event.\n'
    '3. Save the new positions into `sink["offsets"]` **in the same step** as the counts (that is the atomic write).\n'
    '4. Then `c.commit()`, unless `crash_before_commit` is true (the process died).\n\n'
    'Return the number of records read. Use `sink.setdefault` so an empty dict works.',
  tests=[['crash and restart: no double counting', 'from minilake import Broker\nb = Broker(); b.create_topic("trip_events", 3)\nfor i in range(30): b.produce("trip_events", "t%d" % i, json.dumps({"event_type": "requested", "zone_id": i % 2}))\nsink = {}\nrun_batch(b, sink, crash_before_commit=True)\nrun_batch(b, sink)\nsink["counts"]', {'0': 15, '1': 15}],
         ['new events are picked up', 'from minilake import Broker\nb = Broker(); b.create_topic("trip_events", 3)\nsink = {}\nb.produce("trip_events", "x", json.dumps({"event_type": "requested", "zone_id": 7}))\nrun_batch(b, sink)\nb.produce("trip_events", "y", json.dumps({"event_type": "requested", "zone_id": 7}))\n[run_batch(b, sink), sink["counts"]["7"]]', [1, 2]]],
  h=['Two dicts inside the sink: counts and offsets.', 'Seek every partition to the sink\'s offset before polling.', 'Write counts and offsets together; commit to Kafka only afterwards.', 'sink.setdefault("counts", {}); sink.setdefault("offsets", {})\nfor p in c.partitions:\n    c.seek(p, sink["offsets"].get(p, 0))'],
  sol='import json\n\n\ndef run_batch(broker, sink, crash_before_commit=False):\n    counts = sink.setdefault("counts", {})\n    offsets = sink.setdefault("offsets", {})\n    c = broker.consumer("demand", "trip_events")\n    for p in c.partitions:\n        c.seek(p, offsets.get(p, 0))\n    recs = c.poll(100000)\n    for r in recs:\n        e = json.loads(r["value"])\n        if e.get("event_type") == "requested":\n            k = str(e["zone_id"])\n            counts[k] = counts.get(k, 0) + 1\n    for p in c.partitions:\n        offsets[p] = c.pos[p]\n    if not crash_before_commit:\n        c.commit()\n    return len(recs)',
  why='Exactly-once end to end needs a replayable source and a sink that stores its progress atomically with the data (Spark checkpoints, Flink two-phase commit, an idempotent MERGE): the kill -9 test in the lab.')
q(m='s05', t='A poison message goes to the dead-letter queue', lv=E, sig='import json\n\n\ndef parse_records(records, dlq):\n    pass\n',
  p='`records` are dicts from `poll()` (`partition`, `offset`, `key`, `value`). Parse each value as JSON. A record that is not valid JSON, or has no `event_id`, must not stop the stream: append `{"topic": "trip_events", "partition": ..., "offset": ..., "error": short text}` to `dlq` and continue. Return the parsed events in order.',
  tests=[['the stream goes on', 'dlq = []\nr = parse_records([{"partition": 0, "offset": 0, "key": "a", "value": \'{"event_id": "e1"}\'}, {"partition": 0, "offset": 1, "key": "b", "value": "not json"}, {"partition": 1, "offset": 5, "key": "c", "value": \'{"zone_id": 3}\'}, {"partition": 0, "offset": 2, "key": "d", "value": \'{"event_id": "e2"}\'}], dlq)\n[[e["event_id"] for e in r], [(d["partition"], d["offset"]) for d in dlq], all(d["error"] and d["topic"] == "trip_events" for d in dlq)]', [['e1', 'e2'], [[0, 1], [1, 5]], True]]],
  h=['try/except around json.loads; check the field after parsing.', 'Keep the partition and offset: that is how you find and replay the record later.', 'except ValueError as e: dlq.append({...})', 'if not isinstance(e, dict) or "event_id" not in e:'],
  sol='import json\n\n\ndef parse_records(records, dlq):\n    out = []\n    for r in records:\n        try:\n            e = json.loads(r["value"])\n            if not isinstance(e, dict) or "event_id" not in e:\n                raise ValueError("missing event_id")\n        except ValueError as err:\n            dlq.append({"topic": "trip_events", "partition": r["partition"], "offset": r["offset"], "error": str(err)[:200]})\n            continue\n        out.append(e)\n    return out',
  why='Without a dead-letter path one bad message stops the stream and lag grows forever; with it you contain, alert and replay after the fix.')
q(m='s05', t='Schema evolution: accept the safe change, reject the rename', lv=E, sig='def backward_compatible(old, new):\n    pass\n',
  p='A schema maps field name to `{"type": ..., "default": ...}` (default optional). The new schema is **backward compatible** when a consumer using it can read data written with the old one: every field in `new` either exists in `old` with the same type, or has a default. Return `True` or `False`.',
  tests=[['add an optional field with a default', 'backward_compatible({"trip_id": {"type": "string"}}, {"trip_id": {"type": "string"}, "promo_code": {"type": "string", "default": ""}})', True],
         ['rename a field', 'backward_compatible({"zone_id": {"type": "int"}}, {"zone": {"type": "int"}})', False],
         ['change a type', 'backward_compatible({"fare": {"type": "double"}}, {"fare": {"type": "string"}})', False],
         ['remove a field', 'backward_compatible({"a": {"type": "int"}, "b": {"type": "int"}}, {"a": {"type": "int"}})', True]],
  h=['Check each field of the new schema.', 'Same name and same type in old: fine.', 'Not in old: fine only with a default.', 'all((f in old and old[f]["type"] == s["type"]) or "default" in s for f, s in new.items())'],
  sol='def backward_compatible(old, new):\n    return all((f in old and old[f]["type"] == s["type"]) or "default" in s for f, s in new.items())',
  why='Schema registries enforce exactly this check, so a producer cannot break running consumers; a rename is a remove plus an add without a default.')

# ---------- Module 6: change data capture, in the browser ----------
q(m='s06', t='Change events to a current-state table, with an LSN guard', lv=M, sig='def apply_changes(table, events):\n    pass\n',
  p='Events look like Debezium\'s: `{"op": "c" | "u" | "d" | "r", "before": {...} or None, "after": {...} or None, "source": {"lsn": n}}`, and every row has an `id`. `table` maps id to `{"row": {...} or None, "lsn": n}` (a deleted row keeps its LSN with `row` None).\n\n'
    'Apply the events in the order given: create, read (snapshot) and update set the row to `after`; delete sets it to None. **Ignore any event whose LSN is not newer than the key\'s stored LSN**: events can arrive twice or out of order. Return the live rows sorted by id.',
  tests=[['insert, update, delete', 't = {}\napply_changes(t, [{"op": "c", "before": None, "after": {"id": 1, "status": "new"}, "source": {"lsn": 10}}, {"op": "c", "before": None, "after": {"id": 2, "status": "new"}, "source": {"lsn": 11}}, {"op": "u", "before": {"id": 1, "status": "new"}, "after": {"id": 1, "status": "paid"}, "source": {"lsn": 12}}, {"op": "d", "before": {"id": 2, "status": "new"}, "after": None, "source": {"lsn": 13}}])', [{'id': 1, 'status': 'paid'}]],
         ['an old update arriving late is ignored', 't = {}\napply_changes(t, [{"op": "u", "before": None, "after": {"id": 1, "status": "shipped"}, "source": {"lsn": 20}}, {"op": "u", "before": None, "after": {"id": 1, "status": "paid"}, "source": {"lsn": 15}}])', [{'id': 1, 'status': 'shipped'}]],
         ['a delete is not undone by a late insert', 't = {}\napply_changes(t, [{"op": "d", "before": {"id": 3}, "after": None, "source": {"lsn": 9}}, {"op": "c", "before": None, "after": {"id": 3, "status": "new"}, "source": {"lsn": 5}}])', []],
         ['replaying everything changes nothing', 'ev = [{"op": "c", "before": None, "after": {"id": 1, "v": 1}, "source": {"lsn": 1}}, {"op": "u", "before": None, "after": {"id": 1, "v": 2}, "source": {"lsn": 2}}]\nt = {}\na = apply_changes(t, ev)\nb = apply_changes(t, ev)\na == b == [{"id": 1, "v": 2}]', True]],
  h=['One dict per key: the row and the LSN it came from.', 'The key comes from after, or from before for a delete.', 'if key in table and event_lsn <= table[key]["lsn"]: skip', 'k = (e["after"] or e["before"])["id"]\nrow = None if e["op"] == "d" else e["after"]'],
  sol='def apply_changes(table, events):\n    for e in events:\n        k = (e["after"] or e["before"])["id"]\n        lsn = e["source"]["lsn"]\n        if k in table and lsn <= table[k]["lsn"]:\n            continue\n        table[k] = {"row": None if e["op"] == "d" else e["after"], "lsn": lsn}\n    return [v["row"] for _, v in sorted(table.items()) if v["row"] is not None]',
  why='The silver merge of a CDC pipeline: latest change per key wins by log position, not arrival order, and deletes are first-class. Replays must be no-ops.')
q(m='s06', t='Reconcile source and target row by row', lv=E, sig='def diff_keys(source, target):\n    pass\n',
  p='`source` and `target` are lists of rows with an `id`. Return `{"missing": [...], "extra": [...], "different": [...]}`: ids only in the source, ids only in the target, and ids in both whose rows are not equal. Each list sorted.',
  tests=[['three kinds of drift', 'diff_keys([{"id": 1, "amt": 10}, {"id": 2, "amt": 20}, {"id": 3, "amt": 30}], [{"id": 2, "amt": 25}, {"id": 3, "amt": 30}, {"id": 4, "amt": 40}])', {'missing': [1], 'extra': [4], 'different': [2]}],
         ['in sync', 'diff_keys([{"id": 1}], [{"id": 1}])', {'missing': [], 'extra': [], 'different': []}]],
  h=['Index both sides by id.', 's = {r["id"]: r for r in source}', 'Set differences give missing and extra; compare rows for the common ids.', 'different = sorted(k for k in s.keys() & t.keys() if s[k] != t[k])'],
  sol='def diff_keys(source, target):\n    s = {r["id"]: r for r in source}\n    t = {r["id"]: r for r in target}\n    return {"missing": sorted(s.keys() - t.keys()), "extra": sorted(t.keys() - s.keys()), "different": sorted(k for k in s.keys() & t.keys() if s[k] != t[k])}',
  why='Classifying drift by key tells you the repair: re-snapshot missing keys, delete extras, re-merge differences.')
q(m='s06', t='Find the hours where database and lake disagree', lv=M, sig='def drift_hours(source, target):\n    pass\n',
  p='Rows have `id`, `amount` and `updated_at` (ISO). Comparing every row nightly is too slow, so compare per hour: for each hour (`updated_at[:13]`), the row count and the sum of `amount` (rounded to 2 places). Return the sorted list of hours where the two sides differ, including hours present on only one side.',
  tests=[['one bad hour', 'src = [{"id": 1, "amount": 10.0, "updated_at": "2026-10-11T09:05:00"}, {"id": 2, "amount": 5.5, "updated_at": "2026-10-11T09:40:00"}, {"id": 3, "amount": 7.0, "updated_at": "2026-10-11T10:01:00"}]\ndst = [{"id": 1, "amount": 10.0, "updated_at": "2026-10-11T09:05:00"}, {"id": 3, "amount": 7.0, "updated_at": "2026-10-11T10:01:00"}]\ndrift_hours(src, dst)', ['2026-10-11T09']],
         ['an hour only in the target', 'drift_hours([], [{"id": 9, "amount": 1.0, "updated_at": "2026-10-11T03:00:00"}])', ['2026-10-11T03']],
         ['same totals, no drift', 'r = [{"id": 1, "amount": 0.1, "updated_at": "2026-10-11T01:00:00"}, {"id": 2, "amount": 0.2, "updated_at": "2026-10-11T01:30:00"}]\ndrift_hours(r, list(reversed(r)))', []]],
  h=['A summary per hour for each side, then compare.', 'def summary(rows): returns {hour: (count, round(sum, 2))}', 'Hours from both sides: a.keys() | b.keys().', 'sorted(h for h in a.keys() | b.keys() if a.get(h) != b.get(h))'],
  sol='def drift_hours(source, target):\n    def summary(rows):\n        out = {}\n        for r in rows:\n            h = r["updated_at"][:13]\n            n, s = out.get(h, (0, 0.0))\n            out[h] = (n + 1, s + r["amount"])\n        return {h: (n, round(s, 2)) for h, (n, s) in out.items()}\n    a, b = summary(source), summary(target)\n    return sorted(h for h in a.keys() | b.keys() if a.get(h) != b.get(h))',
  why='Cheap aggregates per time bucket find drift fast; you go to row level (the previous exercise) only for the flagged hours.')
q(m='s06', t='Propose, approve, execute: a fix that waits for a person', lv=M, sig='class Fixes:\n    def __init__(self):\n        self.items = {}\n\n    def propose(self, sql, reason, rows):\n        pass\n\n    def approve(self, fix_id, approver):\n        pass\n\n    def execute(self, fix_id, run):\n        pass\n',
  p='An agent may **propose** a repair; only a person may **approve** it; and it runs **once**.\n\n'
    '- `propose(sql, reason, rows)` stores `{"sql", "reason", "rows", "status": "pending", "approver": None}` under ids 1, 2, 3, ... and returns the id.\n'
    '- `approve(fix_id, approver)` sets status `approved` and the approver. An empty approver raises `ValueError`.\n'
    '- `execute(fix_id, run)` calls `run(sql)` only when the status is `approved`, then sets `executed` and returns what `run` returned. Otherwise it raises `PermissionError` (pending, or already executed).',
  tests=[['the normal flow', 'f = Fixes()\ni = f.propose("delete from orders where id = 7", "extra row after drift", 1)\nf.approve(i, "raghav")\n[f.execute(i, lambda s: "ran: " + s), f.items[i]["status"], f.items[i]["approver"]]', ['ran: delete from orders where id = 7', 'executed', 'raghav']],
         ['no approval, no run', 'f = Fixes()\ni = f.propose("update x", "r", 3)\nran = []\ntry:\n    f.execute(i, ran.append)\n    out = "ran"\nexcept PermissionError:\n    out = "refused"\n[out, ran]', ['refused', []]],
         ['runs once', 'f = Fixes()\ni = f.propose("update x", "r", 3); f.approve(i, "me"); f.execute(i, lambda s: 1)\ntry:\n    f.execute(i, lambda s: 2); out = "ran twice"\nexcept PermissionError:\n    out = "refused"\nout', 'refused'],
         ['ids count up', 'f = Fixes()\n[f.propose("a", "r", 1), f.propose("b", "r", 1)]', [1, 2]]],
  h=['Three methods around one status field.', 'The id is len(self.items) + 1.', 'execute checks the status before calling run.', 'if self.items[fix_id]["status"] != "approved":\n    raise PermissionError("not approved")'],
  sol='class Fixes:\n    def __init__(self):\n        self.items = {}\n\n    def propose(self, sql, reason, rows):\n        i = len(self.items) + 1\n        self.items[i] = {"sql": sql, "reason": reason, "rows": rows, "status": "pending", "approver": None}\n        return i\n\n    def approve(self, fix_id, approver):\n        if not approver:\n            raise ValueError("an approver is required")\n        self.items[fix_id]["status"] = "approved"\n        self.items[fix_id]["approver"] = approver\n\n    def execute(self, fix_id, run):\n        f = self.items[fix_id]\n        if f["status"] != "approved":\n            raise PermissionError("fix " + str(fix_id) + " is " + f["status"])\n        out = run(f["sql"])\n        f["status"] = "executed"\n        return out',
  why='The control that matters for agents with write access: the agent has no path to execute without a recorded human approval, and a fix cannot run twice.')

# ---------- Module O1: data products, contracts and SLOs, in the browser ----------
q(m='o01', t='Check a data contract', lv=M, sig='def check_contract(contract, rows):\n    pass\n',
  p='A contract looks like `{"key": "trip_id", "columns": {"trip_id": {"type": "string", "required": True}, "fare_usd": {"type": "number", "required": True, "min": 0}, "status": {"type": "string", "allowed": ["completed", "refunded"]}}}`. Types are `"string"`, `"int"` and `"number"` (int or float). A boolean is never an int or a number.\n\n'
    'Check every row (a dict) and return every violation as `[row_index, column, problem]`, sorted by row then column. Problems:\n\n'
    '- `"missing"`: a required column is absent or None.\n'
    '- `"type"`: a value that is not None has the wrong type (then skip the other checks for that value).\n'
    '- `"not allowed"`: the value is not in `allowed`.\n'
    '- `"below min"`: the value is less than `min`.\n'
    '- `"duplicate"`: the key column\'s value was already seen in an earlier row (report it on the later row, column = the key).\n\n'
    'Optional columns may be absent or None. Columns not in the contract are ignored.',
  tests=[['a clean batch', 'check_contract({"key": "id", "columns": {"id": {"type": "string", "required": True}, "n": {"type": "int"}}}, [{"id": "a", "n": 1}, {"id": "b"}, {"id": "c", "n": None, "extra": 5}])', []],
         ['missing and wrong types', 'check_contract({"key": "id", "columns": {"id": {"type": "string", "required": True}, "n": {"type": "int", "required": True}, "x": {"type": "number"}}}, [{"id": "a", "n": "5"}, {"n": 2, "x": True}, {"id": "c", "n": 3.0, "x": 1}])', [[0, 'n', 'type'], [1, 'id', 'missing'], [1, 'x', 'type'], [2, 'n', 'type']]],
         ['allowed values and minimum', 'check_contract({"key": "id", "columns": {"id": {"type": "int", "required": True}, "fare": {"type": "number", "min": 0}, "status": {"type": "string", "allowed": ["done", "refunded"]}}}, [{"id": 1, "fare": -2.5, "status": "done"}, {"id": 2, "fare": 0, "status": "lost"}, {"id": 3, "fare": "1", "status": "refunded"}])', [[0, 'fare', 'below min'], [1, 'status', 'not allowed'], [2, 'fare', 'type']]],
         ['duplicate keys reported on the later rows', 'check_contract({"key": "id", "columns": {"id": {"type": "string", "required": True}}}, [{"id": "a"}, {"id": "b"}, {"id": "a"}, {"id": "a"}])', [[2, 'id', 'duplicate'], [3, 'id', 'duplicate']]],
         ['a boolean is not an int', 'check_contract({"key": "id", "columns": {"id": {"type": "int", "required": True}}}, [{"id": True}, {"id": 0}])', [[0, 'id', 'type']]]],
  h=['Loop over rows with enumerate, then over the contract\'s columns.', 'Write a small helper that answers "is this value of this type?" and rejects bool first.', 'Keep a set of key values seen so far for the duplicate check.', 'def ok_type(v, t):\n    if isinstance(v, bool): return False\n    return {"string": isinstance(v, str), "int": isinstance(v, int), "number": isinstance(v, (int, float))}[t]'],
  sol='def check_contract(contract, rows):\n    def ok_type(v, t):\n        if isinstance(v, bool):\n            return False\n        return {"string": isinstance(v, str), "int": isinstance(v, int), "number": isinstance(v, (int, float))}[t]\n    out, seen, key = [], set(), contract["key"]\n    for i, row in enumerate(rows):\n        for col, spec in contract["columns"].items():\n            v = row.get(col)\n            if v is None:\n                if spec.get("required"):\n                    out.append([i, col, "missing"])\n                continue\n            if not ok_type(v, spec["type"]):\n                out.append([i, col, "type"])\n                continue\n            if "allowed" in spec and v not in spec["allowed"]:\n                out.append([i, col, "not allowed"])\n            if "min" in spec and v < spec["min"]:\n                out.append([i, col, "below min"])\n        k = row.get(key)\n        if k is not None:\n            if k in seen:\n                out.append([i, key, "duplicate"])\n            seen.add(k)\n    return sorted(out, key=lambda x: (x[0], x[1]))',
  why='A data product\'s contract is only useful if the platform checks it on every change and every run; this is the check, and publication waits until it passes.')
q(m='o01', t='SLO report and error budget', lv=M, sig='import datetime as dt\n\n\ndef slo_report(slo, runs):\n    pass\n',
  p='`slo` is `{"ready_by": "06:00", "target": 0.99}`. `runs` lists daily runs like `{"date": "2026-10-01", "ready_at": "05:40"}`; `ready_at` is None when the run failed. A day is **met** when its run has `ready_at` at or before `ready_by` (both `HH:MM`). Days between the first and last date that have **no run at all** are missed too.\n\n'
    'Return `{"days": n, "met": k, "attainment": round(k / n, 4), "budget": allowed_misses, "budget_left": allowed_misses - misses, "ok": attainment >= target, "missed": [dates not met, sorted]}`, where `allowed_misses = int(n * (1 - target) + 1e-9)` and `misses = n - k`. With no runs, return days 0, met 0, attainment 1.0, budget 0, budget_left 0, ok True and an empty list.',
  tests=[['every day on time', 'slo_report({"ready_by": "06:00", "target": 0.9}, [{"date": "2026-10-0%d" % d, "ready_at": "05:00"} for d in range(1, 4)])', {'days': 3, 'met': 3, 'attainment': 1.0, 'budget': 0, 'budget_left': 0, 'ok': True, 'missed': []}],
         ['late, failed and exactly on time', 'slo_report({"ready_by": "06:00", "target": 0.5}, [{"date": "2026-10-01", "ready_at": "06:00"}, {"date": "2026-10-02", "ready_at": "06:01"}, {"date": "2026-10-03", "ready_at": None}, {"date": "2026-10-04", "ready_at": "04:10"}])', {'days': 4, 'met': 2, 'attainment': 0.5, 'budget': 2, 'budget_left': 0, 'ok': True, 'missed': ['2026-10-02', '2026-10-03']}],
         ['a day with no run counts as missed, runs out of order', 'slo_report({"ready_by": "06:00", "target": 0.9}, [{"date": "2026-10-05", "ready_at": "05:00"}, {"date": "2026-10-01", "ready_at": "05:00"}, {"date": "2026-10-02", "ready_at": "05:00"}])', {'days': 5, 'met': 3, 'attainment': 0.6, 'budget': 0, 'budget_left': -2, 'ok': False, 'missed': ['2026-10-03', '2026-10-04']}],
         ['a month at 90 percent', 'slo_report({"ready_by": "07:00", "target": 0.9}, [{"date": (dt.date(2026, 9, 1) + dt.timedelta(days=i)).isoformat(), "ready_at": "08:00" if i in (3, 9) else "06:30"} for i in range(30)])', {'days': 30, 'met': 28, 'attainment': 0.9333, 'budget': 3, 'budget_left': 1, 'ok': True, 'missed': ['2026-09-04', '2026-09-10']}],
         ['no runs', 'slo_report({"ready_by": "06:00", "target": 0.99}, [])', {'days': 0, 'met': 0, 'attainment': 1.0, 'budget': 0, 'budget_left': 0, 'ok': True, 'missed': []}]],
  h=['Turn the dates into date objects and find the first and last.', 'Walk every day from first to last, not only the days that have a run.', '"HH:MM" strings compare correctly as strings.', 'by = {r["date"]: r for r in runs}\nd = first\nwhile d <= last:\n    r = by.get(d.isoformat())\n    ...\n    d += dt.timedelta(days=1)'],
  sol='import datetime as dt\n\n\ndef slo_report(slo, runs):\n    if not runs:\n        return {"days": 0, "met": 0, "attainment": 1.0, "budget": 0, "budget_left": 0, "ok": True, "missed": []}\n    by = {r["date"]: r for r in runs}\n    ds = sorted(dt.date.fromisoformat(r["date"]) for r in runs)\n    d, met, missed = ds[0], 0, []\n    while d <= ds[-1]:\n        r = by.get(d.isoformat())\n        if r and r["ready_at"] is not None and r["ready_at"] <= slo["ready_by"]:\n            met += 1\n        else:\n            missed.append(d.isoformat())\n        d += dt.timedelta(days=1)\n    n = (ds[-1] - ds[0]).days + 1\n    att = round(met / n, 4)\n    budget = int(n * (1 - slo["target"]) + 1e-9)\n    return {"days": n, "met": met, "attainment": att, "budget": budget, "budget_left": budget - (n - met), "ok": att >= slo["target"], "missed": missed}',
  why='Service levels are what make a dataset a product; the error budget tells the owner when to stop shipping features and fix reliability.')
q(m='o01', t='Breaking or not: diff two contract versions', lv=M, sig='def contract_diff(old, new):\n    pass\n',
  p='A contract version is `{"grain": "one row per trip", "columns": {name: {"type": ..., "required": bool}}}` (`required` may be absent, meaning False). Compare `old` with `new` and return `{"breaking": [...], "additive": [...], "bump": ...}`:\n\n'
    '- Breaking: `"removed X"` (a column is gone), `"type X"` (its type changed), `"required X"` (an existing column became required), `"grain"` (the grain text changed).\n'
    '- Additive: `"added X"` for each new column.\n'
    '- `bump` is `"major"` if anything is breaking, else `"minor"` if anything is additive, else `"none"`.\n\n'
    'Sort both lists. A column that became optional is neither.',
  tests=[['nothing changed', 'contract_diff({"grain": "trip", "columns": {"a": {"type": "int"}}}, {"grain": "trip", "columns": {"a": {"type": "int", "required": False}}})', {'breaking': [], 'additive': [], 'bump': 'none'}],
         ['an added column is minor', 'contract_diff({"grain": "trip", "columns": {"a": {"type": "int"}}}, {"grain": "trip", "columns": {"a": {"type": "int"}, "b": {"type": "string", "required": True}}})', {'breaking': [], 'additive': ['added b'], 'bump': 'minor'}],
         ['remove, retype and require', 'contract_diff({"grain": "trip", "columns": {"a": {"type": "int"}, "b": {"type": "string"}, "c": {"type": "number"}, "d": {"type": "int", "required": True}}}, {"grain": "trip", "columns": {"b": {"type": "int"}, "c": {"type": "number", "required": True}, "d": {"type": "int"}, "e": {"type": "int"}}})', {'breaking': ['removed a', 'required c', 'type b'], 'additive': ['added e'], 'bump': 'major'}],
         ['a new grain breaks everyone', 'contract_diff({"grain": "one row per trip", "columns": {"a": {"type": "int"}}}, {"grain": "one row per trip leg", "columns": {"a": {"type": "int"}}})', {'breaking': ['grain'], 'additive': [], 'bump': 'major'}]],
  h=['Columns in old but not in new were removed; in new but not in old were added.', 'For columns in both, compare type, and required (only False to True breaks).', 'Use .get("required", False) for the default.', 'for c in old["columns"]:\n    if c not in new["columns"]:\n        breaking.append("removed " + c)'],
  sol='def contract_diff(old, new):\n    o, n = old["columns"], new["columns"]\n    breaking, additive = [], []\n    if old["grain"] != new["grain"]:\n        breaking.append("grain")\n    for c in o:\n        if c not in n:\n            breaking.append("removed " + c)\n            continue\n        if o[c]["type"] != n[c]["type"]:\n            breaking.append("type " + c)\n        if n[c].get("required", False) and not o[c].get("required", False):\n            breaking.append("required " + c)\n    for c in n:\n        if c not in o:\n            additive.append("added " + c)\n    bump = "major" if breaking else "minor" if additive else "none"\n    return {"breaking": sorted(breaking), "additive": sorted(additive), "bump": bump}',
  why='Consumers depend on the contract, not the code; a breaking change ships as a new major version beside the old one, with a notice period.')
q(m='o01', t='Adoption report: can this product be retired?', lv=E, sig='import datetime as dt\n\n\ndef adoption(log, today, days=90):\n    pass\n',
  p='`log` lists reads of one data product: `{"date": "2026-10-01", "consumer": "finance-daily", "kind": "user" | "job" | "product"}`. `today` is a date string. A read is **recent** when its date is after today minus `days` days, and **this week** when it is after today minus 7 days (so a read exactly 7 days ago is not this week).\n\n'
    'Return `{"weekly_active": [consumers that read this week, sorted, no repeats], "dependent_products": [consumers of kind "product" with a recent read, sorted], "last_read": the latest date or None, "can_retire": True only if there is no recent read}`.',
  tests=[['no reads at all', 'adoption([], "2026-11-01")', {'weekly_active': [], 'dependent_products': [], 'last_read': None, 'can_retire': True}],
         ['weekly boundary and repeats', 'adoption([{"date": "2026-11-01", "consumer": "b", "kind": "user"}, {"date": "2026-10-26", "consumer": "a", "kind": "job"}, {"date": "2026-10-25", "consumer": "c", "kind": "user"}, {"date": "2026-10-30", "consumer": "b", "kind": "user"}], "2026-11-01")', {'weekly_active': ['a', 'b'], 'dependent_products': [], 'last_read': '2026-11-01', 'can_retire': False}],
         ['a dependent product keeps it alive', 'adoption([{"date": "2026-09-01", "consumer": "revenue", "kind": "product"}, {"date": "2026-05-01", "consumer": "old", "kind": "product"}], "2026-11-01")', {'weekly_active': [], 'dependent_products': ['revenue'], 'last_read': '2026-09-01', 'can_retire': False}],
         ['exactly 90 days ago is not recent', 'adoption([{"date": "2026-08-03", "consumer": "x", "kind": "user"}], "2026-11-01")', {'weekly_active': [], 'dependent_products': [], 'last_read': '2026-08-03', 'can_retire': True}]],
  h=['Parse today once and compute the two cut-off dates.', '"After today minus N days" means date > today - N days.', 'Use sets, then sorted().', 'week = t - dt.timedelta(days=7)\nrecent = t - dt.timedelta(days=days)'],
  sol='import datetime as dt\n\n\ndef adoption(log, today, days=90):\n    t = dt.date.fromisoformat(today)\n    week, recent = t - dt.timedelta(days=7), t - dt.timedelta(days=days)\n    wa, dep, rec = set(), set(), False\n    for r in log:\n        d = dt.date.fromisoformat(r["date"])\n        if d > week:\n            wa.add(r["consumer"])\n        if d > recent:\n            rec = True\n            if r["kind"] == "product":\n                dep.add(r["consumer"])\n    return {"weekly_active": sorted(wa), "dependent_products": sorted(dep), "last_read": max((r["date"] for r in log), default=None), "can_retire": not rec}',
  why='Products are measured by who uses them, and retired on evidence: no recent readers, no dependent products, then a deprecation notice.')

# ---------- Module O2: golden paths and templates, in the browser ----------
q(m='o02', t='Render a template with checked parameters', lv=M, sig='import re\n\n\ndef render(template, params):\n    pass\n',
  p='A template is `{"params": {name: {"required": bool, "default": value, "pattern": regex}}, "files": {path: content}}`. Paths and contents use `{{name}}` placeholders.\n\n'
    '1. Build the values: a given param wins; else its `default`; a required param with neither is an error `"missing NAME"`.\n'
    '2. A value with a `pattern` must match it fully (`re.fullmatch`), else `"invalid NAME"`.\n'
    '3. Any `{{x}}` in a path or content whose `x` is not a declared param is `"unknown x"` (report each name once).\n\n'
    'Return `{"errors": sorted errors, "files": {}}` if there are errors; otherwise `{"errors": [], "files": {rendered path: rendered content}}`. Params given but not declared are ignored.',
  tests=[['renders paths and contents with a default', 'render({"params": {"name": {"required": True, "pattern": "[a-z][a-z0-9_]*"}, "owner": {"required": True}, "schedule": {"default": "@daily"}}, "files": {"{{name}}/contract.yaml": "product: {{name}}\\nowner: {{owner}}", "{{name}}/job.yaml": "schedule: {{schedule}}"}}, {"name": "trips", "owner": "team-trips"})', {'errors': [], 'files': {'trips/contract.yaml': 'product: trips\nowner: team-trips', 'trips/job.yaml': 'schedule: @daily'}}],
         ['missing and invalid parameters', 'render({"params": {"name": {"required": True, "pattern": "[a-z][a-z0-9_]*"}, "owner": {"required": True}}, "files": {"a": "{{name}} {{owner}}"}}, {"name": "Trips-1"})', {'errors': ['invalid name', 'missing owner'], 'files': {}}],
         ['an undeclared placeholder is reported once', 'render({"params": {"name": {"required": True}}, "files": {"{{name}}/{{team}}.md": "{{team}} owns {{name}}", "x": "{{cost}}"}}, {"name": "a", "team": "ignored"})', {'errors': ['unknown cost', 'unknown team'], 'files': {}}],
         ['the pattern must match the whole value', 'render({"params": {"name": {"required": True, "pattern": "[a-z]+"}}, "files": {"f": "{{name}}"}}, {"name": "abc1"})', {'errors': ['invalid name'], 'files': {}}],
         ['a given value beats the default', 'render({"params": {"schedule": {"default": "@daily"}}, "files": {"j": "{{schedule}}"}}, {"schedule": "@hourly"})', {'errors': [], 'files': {'j': '@hourly'}}]],
  h=['Work out every value first, then render.', 'Find placeholders with re.findall(r"{{(\\w+)}}", text) in paths and contents.', 'Use a set for errors so an unknown name is reported once.', 'for k, spec in template["params"].items():\n    v = params.get(k, spec.get("default"))'],
  sol='import re\n\n\ndef render(template, params):\n    errs, vals = set(), {}\n    for k, spec in template["params"].items():\n        v = params[k] if k in params else spec.get("default")\n        if v is None:\n            if spec.get("required"):\n                errs.add("missing " + k)\n            continue\n        if "pattern" in spec and not re.fullmatch(spec["pattern"], str(v)):\n            errs.add("invalid " + k)\n        vals[k] = str(v)\n    for path, body in template["files"].items():\n        for name in re.findall(r"{{(\\w+)}}", path + "\\n" + body):\n            if name not in template["params"]:\n                errs.add("unknown " + name)\n    if errs:\n        return {"errors": sorted(errs), "files": {}}\n    sub = lambda t: re.sub(r"{{(\\w+)}}", lambda m: vals.get(m.group(1), ""), t)\n    return {"errors": [], "files": {sub(p): sub(b) for p, b in template["files"].items()}}',
  why='A scaffolder that checks its inputs before writing anything gives every team a working, consistent start; bad names are refused, not discovered in production.')
q(m='o02', t='Template drift: how far behind is each repository?', lv=M, sig='def drift(latest, repos):\n    pass\n',
  p='`latest` is the current template: `{"version": "2.3.1", "files": {path: hash}}`. Each repository is `{"name": ..., "version": "2.1.0", "files": {path: hash}}` (the template version it was made from, and the hashes of its template-managed files today).\n\n'
    'For each repository return `{"repo": name, "behind": level, "missing": [...], "modified": [...]}`, sorted by repo, where `level` compares versions as numbers (major.minor.patch): `"major"` if the major is lower, else `"minor"` if the minor is lower, else `"patch"` if the patch is lower, else `"none"`. `missing` lists template files the repository lacks; `modified` lists files it has with a different hash. Both sorted. Files the template does not manage are ignored.',
  tests=[['up to date', 'drift({"version": "1.2.0", "files": {"ci.yml": "a"}}, [{"name": "x", "version": "1.2.0", "files": {"ci.yml": "a", "own.py": "z"}}])', [{'repo': 'x', 'behind': 'none', 'missing': [], 'modified': []}]],
         ['major, minor and patch behind', 'drift({"version": "2.3.1", "files": {}}, [{"name": "c", "version": "2.3.0", "files": {}}, {"name": "a", "version": "1.9.9", "files": {}}, {"name": "b", "version": "2.1.5", "files": {}}])', [{'repo': 'a', 'behind': 'major', 'missing': [], 'modified': []}, {'repo': 'b', 'behind': 'minor', 'missing': [], 'modified': []}, {'repo': 'c', 'behind': 'patch', 'missing': [], 'modified': []}]],
         ['versions compare as numbers, not text', 'drift({"version": "1.10.0", "files": {}}, [{"name": "a", "version": "1.9.0", "files": {}}, {"name": "b", "version": "1.10.0", "files": {}}])', [{'repo': 'a', 'behind': 'minor', 'missing': [], 'modified': []}, {'repo': 'b', 'behind': 'none', 'missing': [], 'modified': []}]],
         ['missing and modified files', 'drift({"version": "1.0.0", "files": {"ci.yml": "a", "contract.yaml": "b", "README.md": "c"}}, [{"name": "r", "version": "1.0.0", "files": {"ci.yml": "x", "README.md": "c"}}])', [{'repo': 'r', 'behind': 'none', 'missing': ['contract.yaml'], 'modified': ['ci.yml']}]]],
  h=['Turn "2.3.1" into the tuple (2, 3, 1) with int().', 'Compare the major first, then the minor, then the patch.', 'Walk the template\'s files, not the repository\'s.', 'v = lambda s: tuple(int(x) for x in s.split("."))'],
  sol='def drift(latest, repos):\n    v = lambda s: tuple(int(x) for x in s.split("."))\n    L, out = v(latest["version"]), []\n    for r in repos:\n        R = v(r["version"])\n        level = "major" if R[0] < L[0] else "minor" if R[:2] < L[:2] else "patch" if R < L else "none"\n        miss = sorted(f for f in latest["files"] if f not in r["files"])\n        mod = sorted(f for f, h in latest["files"].items() if f in r["files"] and r["files"][f] != h)\n        out.append({"repo": r["name"], "behind": level, "missing": miss, "modified": mod})\n    return sorted(out, key=lambda x: x["repo"])',
  why='A template is copied once and then drifts; knowing which repositories are how far behind is what lets a platform team ship fixes to everyone.')
q(m='o02', t='Guardrails with waivers that expire', lv=E, sig='import datetime as dt\n\n\ndef guardrails(project, waivers, today):\n    pass\n',
  p='Check a project (a dict) against five policies:\n\n'
    '- `"owner"`: `project["owner"]` is a non-empty string.\n'
    '- `"contract"`: `project["contract"]` is True.\n'
    '- `"tests"`: `project["tests"]` is at least 1.\n'
    '- `"pii"`: every column in `project["pii"]` is also in `project["masked"]`.\n'
    '- `"ci"`: `project["ci"]` is True.\n\n'
    'Missing keys count as failing (an empty list for `pii` and `masked`). `waivers` maps a policy to an expiry date string; a failing policy is **waived** while `today` is on or before its expiry. Return `{"fail": [...], "waived": [...], "ok": no unwaived failures}`, lists sorted.',
  tests=[['a clean project', 'guardrails({"owner": "team-a", "contract": True, "tests": 3, "pii": ["email"], "masked": ["email"], "ci": True}, {}, "2026-11-01")', {'fail': [], 'waived': [], 'ok': True}],
         ['missing keys fail', 'guardrails({"owner": "", "tests": 0}, {}, "2026-11-01")', {'fail': ['ci', 'contract', 'owner', 'tests'], 'waived': [], 'ok': False}],
         ['unmasked personal data fails', 'guardrails({"owner": "a", "contract": True, "tests": 1, "pii": ["email", "phone"], "masked": ["email"], "ci": True}, {}, "2026-11-01")', {'fail': ['pii'], 'waived': [], 'ok': False}],
         ['a waiver works until its expiry date, inclusive', 'p = {"owner": "a", "contract": False, "tests": 1, "ci": True}\n[guardrails(p, {"contract": "2026-11-01"}, "2026-11-01")["ok"], guardrails(p, {"contract": "2026-11-01"}, "2026-11-02")["fail"]]', [True, ['contract']]],
         ['a waiver for a passing policy changes nothing', 'guardrails({"owner": "a", "contract": True, "tests": 1, "ci": False}, {"tests": "2027-01-01", "ci": "2027-01-01"}, "2026-11-01")', {'fail': [], 'waived': ['ci'], 'ok': True}]],
  h=['Write each policy as one boolean.', 'project.get(key, default) handles missing keys.', 'Compare ISO dates as strings, or parse them with dt.date.fromisoformat.', 'checks = {"owner": bool(project.get("owner")), ...}'],
  sol='import datetime as dt\n\n\ndef guardrails(project, waivers, today):\n    masked = set(project.get("masked", []))\n    checks = {\n        "owner": isinstance(project.get("owner"), str) and bool(project.get("owner")),\n        "contract": project.get("contract") is True,\n        "tests": project.get("tests", 0) >= 1,\n        "pii": all(c in masked for c in project.get("pii", [])),\n        "ci": project.get("ci") is True,\n    }\n    t = dt.date.fromisoformat(today)\n    fail, waived = [], []\n    for k, ok in checks.items():\n        if ok:\n            continue\n        if k in waivers and t <= dt.date.fromisoformat(waivers[k]):\n            waived.append(k)\n        else:\n            fail.append(k)\n    return {"fail": sorted(fail), "waived": sorted(waived), "ok": not fail}',
  why='Guardrails run on every change and need no reviewer; a waiver with an expiry turns an exception into a dated decision instead of a permanent hole.')
q(m='o02', t='Is the golden path working?', lv=M, sig='import datetime as dt\n\n\ndef path_metrics(projects):\n    pass\n',
  p='Each project is `{"path": "golden" | "custom", "created": "2026-09-01", "first_prod": "2026-09-04" or None, "tickets": n}`. Return:\n\n'
    '- `"adoption"`: share of projects on the golden path, rounded to 2 places (0.0 with no projects).\n'
    '- `"median_days"`: `{"golden": m, "custom": m}`, the median number of days from `created` to `first_prod`, over projects of that path that reached production (the average of the middle two for an even count); None if none did.\n'
    '- `"tickets_per_project"`: `{"golden": x, "custom": x}`, mean tickets per project of that path, rounded to 2 places; None if the path has no projects.',
  tests=[['no projects', 'path_metrics([])', {'adoption': 0.0, 'median_days': {'golden': None, 'custom': None}, 'tickets_per_project': {'golden': None, 'custom': None}}],
         ['golden is faster', 'path_metrics([{"path": "golden", "created": "2026-09-01", "first_prod": "2026-09-03", "tickets": 0}, {"path": "golden", "created": "2026-09-01", "first_prod": "2026-09-08", "tickets": 1}, {"path": "golden", "created": "2026-09-01", "first_prod": "2026-09-05", "tickets": 0}, {"path": "custom", "created": "2026-08-01", "first_prod": "2026-09-10", "tickets": 6}])', {'adoption': 0.75, 'median_days': {'golden': 4, 'custom': 40}, 'tickets_per_project': {'golden': 0.33, 'custom': 6.0}}],
         ['even counts average the middle two; unfinished projects are left out of the median', 'path_metrics([{"path": "custom", "created": "2026-09-01", "first_prod": "2026-09-11", "tickets": 2}, {"path": "custom", "created": "2026-09-01", "first_prod": "2026-09-04", "tickets": 4}, {"path": "custom", "created": "2026-09-01", "first_prod": None, "tickets": 9}])', {'adoption': 0.0, 'median_days': {'golden': None, 'custom': 6.5}, 'tickets_per_project': {'golden': None, 'custom': 5.0}}],
         ['a path with projects but none in production', 'path_metrics([{"path": "golden", "created": "2026-09-01", "first_prod": None, "tickets": 1}, {"path": "custom", "created": "2026-09-01", "first_prod": "2026-09-02", "tickets": 0}])', {'adoption': 0.5, 'median_days': {'golden': None, 'custom': 1}, 'tickets_per_project': {'golden': 1.0, 'custom': 0.0}}]],
  h=['Group projects by path first.', 'Days = (date(first_prod) - date(created)).days.', 'Sort the days before taking the middle.', 'def median(xs):\n    xs = sorted(xs); n = len(xs)\n    return xs[n // 2] if n % 2 else (xs[n // 2 - 1] + xs[n // 2]) / 2'],
  sol='import datetime as dt\n\n\ndef path_metrics(projects):\n    d = dt.date.fromisoformat\n    def median(xs):\n        xs = sorted(xs)\n        n = len(xs)\n        if not n:\n            return None\n        return xs[n // 2] if n % 2 else (xs[n // 2 - 1] + xs[n // 2]) / 2\n    out = {"median_days": {}, "tickets_per_project": {}}\n    for path in ("golden", "custom"):\n        ps = [p for p in projects if p["path"] == path]\n        out["median_days"][path] = median([(d(p["first_prod"]) - d(p["created"])).days for p in ps if p["first_prod"]])\n        out["tickets_per_project"][path] = round(sum(p["tickets"] for p in ps) / len(ps), 2) if ps else None\n    g = sum(1 for p in projects if p["path"] == "golden")\n    out["adoption"] = round(g / len(projects), 2) if projects else 0.0\n    return out',
  why='A golden path is a product: adoption, time to first production run and support load show whether teams choose it and whether it saves them time.')
